#!/usr/bin/env python3
"""The verification gate. Clean exit is the definition of done.

Give the agent a way to verify its work and quality goes up; build the verification,
not the prompt. Anything that writes to briefs/ or topics/library.md runs this before
reporting finished work, and fixes what it reports rather than explaining it away.

What it catches:
  briefs   missing required sections, missing or malformed frontmatter, a section
           left as nothing but scaffold comments, two briefs on one topic, a
           library_id that is not in the topic library
  topics   off-taxonomy status values, a status claiming a brief that does not exist,
           a brief whose topic is not reflected in the library
  links    markdown references to repo files that do not exist
  tools    Python that does not compile

Warnings never fail the run; errors exit 1.

    python3 tools/check.py            all suites
    python3 tools/check.py briefs     one suite
"""

from __future__ import annotations

import argparse
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
BRIEFS = ROOT / "briefs"
LIBRARY = ROOT / "topics" / "library.md"

REQUIRED_SECTIONS = [
    "Core question",
    "The one thing",
    "The misconception",
    "Findings",
    "What we do not know",
    "Application",
    "Anticipated pushback",
    "Sources",
]

REQUIRED_FRONTMATTER = ["topic", "library_id", "category", "researched", "status"]
VALID_BRIEF_STATUS = {"draft", "ready"}
VALID_TOPIC_STATUS = {"idea", "brief", "built", "delivered"}

# Only repo-relative paths. External and home-relative paths are the author's problem,
# not this gate's — it cannot know what is on another machine.
MD_PATH_RE = re.compile(
    r"(?<![\w/~.])((?:context|topics|briefs|agents|commands|tools)/[\w./-]+\.(?:md|py))"
)
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


class Report:
    def __init__(self) -> None:
        self.passed = 0
        self.warnings: list[tuple[str, str]] = []
        self.errors: list[tuple[str, str]] = []

    def ok(self) -> None:
        self.passed += 1

    def warn(self, where: str, msg: str) -> None:
        self.warnings.append((where, msg))

    def error(self, where: str, msg: str) -> None:
        self.errors.append((where, msg))


def frontmatter(text: str) -> dict[str, str] | None:
    if not text.startswith("---\n"):
        return None
    end = text.find("\n---", 4)
    if end == -1:
        return None
    out: dict[str, str] = {}
    for line in text[4:end].splitlines():
        if ":" in line:
            k, _, v = line.partition(":")
            out[k.strip()] = v.strip()
    return out


def library_rows() -> list[dict[str, str]]:
    """Topic rows from topics/library.md: | # | Topic | Hook | Status | Brief |"""
    if not LIBRARY.exists():
        return []
    rows = []
    category = ""
    for n, line in enumerate(LIBRARY.read_text(encoding="utf-8").splitlines(), 1):
        if line.startswith("## "):
            category = line[3:].strip()
            continue
        cells = [c.strip() for c in line.split("|")]
        if len(cells) >= 6 and cells[1].isdigit():
            rows.append({
                "line": str(n), "id": cells[1], "topic": cells[2],
                "status": cells[4].strip("`"), "brief": cells[5], "category": category,
            })
    return rows


# --------------------------------------------------------------------------
# briefs
# --------------------------------------------------------------------------

def check_briefs(r: Report) -> None:
    if not BRIEFS.exists():
        r.warn("briefs/", "directory does not exist yet")
        return

    known_ids = {row["id"] for row in library_rows()}
    seen_slugs: dict[str, str] = {}

    files = [f for f in sorted(BRIEFS.glob("*.md")) if f.name != "README.md"]
    if not files:
        r.warn("briefs/", "no briefs yet — nothing to verify")
        return

    for f in files:
        rel = str(f.relative_to(ROOT))
        text = f.read_text(encoding="utf-8")

        m = re.match(r"^(\d{4}-\d{2}-\d{2})-(.+)\.md$", f.name)
        if not m:
            r.error(rel, "filename is not YYYY-MM-DD-slug.md — use tools/new_brief.py")
            continue
        r.ok()

        slug = m.group(2)
        if slug in seen_slugs:
            r.error(rel, f"second brief on the same topic as {seen_slugs[slug]} — "
                         "improve the first rather than keeping two versions of the truth")
        else:
            seen_slugs[slug] = rel
            r.ok()

        fm = frontmatter(text)
        if fm is None:
            r.error(rel, "missing or malformed YAML frontmatter")
            continue
        r.ok()

        for key in REQUIRED_FRONTMATTER:
            if key not in fm or not fm[key]:
                # category is legitimately empty for an off-library topic
                if key == "category" and fm.get("library_id") == "off-library":
                    r.ok()
                else:
                    r.error(rel, f"frontmatter missing '{key}'")
            else:
                r.ok()

        status = fm.get("status", "")
        if status and status not in VALID_BRIEF_STATUS:
            r.error(rel, f"status '{status}' not in {sorted(VALID_BRIEF_STATUS)}")
        elif status:
            r.ok()

        researched = fm.get("researched", "")
        if researched and not DATE_RE.match(researched):
            r.error(rel, f"researched '{researched}' is not YYYY-MM-DD")
        elif researched:
            r.ok()

        lib = fm.get("library_id", "")
        if lib and lib != "off-library" and known_ids and lib not in known_ids:
            r.error(rel, f"library_id '{lib}' is not a topic in topics/library.md")
        elif lib:
            r.ok()

        # Sections must exist AND carry content. A section holding nothing but the
        # scaffold comments is an unfinished brief wearing a finished brief's shape.
        bodies = split_sections(text)
        for name in REQUIRED_SECTIONS:
            if name not in bodies:
                r.error(rel, f"missing required section '## {name}'")
                continue
            stripped = re.sub(r"<!--.*?-->", "", bodies[name], flags=re.S).strip()
            if not stripped:
                r.error(rel, f"section '## {name}' is empty — scaffold comments are not content")
            else:
                r.ok()

        if fm.get("status") == "ready":
            unknown = re.sub(r"<!--.*?-->", "", bodies.get("What we do not know", ""), flags=re.S)
            if not unknown.strip():
                r.error(rel, "status is 'ready' but 'What we do not know' is empty")
            else:
                r.ok()


def split_sections(text: str) -> dict[str, str]:
    out: dict[str, str] = {}
    current: str | None = None
    buf: list[str] = []
    for line in text.splitlines():
        if line.startswith("## "):
            if current is not None:
                out[current] = "\n".join(buf)
            current = line[3:].strip()
            buf = []
        elif current is not None:
            buf.append(line)
    if current is not None:
        out[current] = "\n".join(buf)
    return out


# --------------------------------------------------------------------------
# topics
# --------------------------------------------------------------------------

def check_topics(r: Report) -> None:
    if not LIBRARY.exists():
        r.error("topics/library.md", "does not exist")
        return

    rows = library_rows()
    if not rows:
        r.error("topics/library.md", "no topic rows parsed — has the table shape changed?")
        return

    ids: dict[str, str] = {}
    for row in rows:
        at = f"topics/library.md:{row['line']}"

        if row["status"] not in VALID_TOPIC_STATUS:
            r.error(at, f"status '{row['status']}' not in {sorted(VALID_TOPIC_STATUS)}")
        else:
            r.ok()

        if row["id"] in ids:
            r.error(at, f"topic number {row['id']} already used by '{ids[row['id']]}'")
        else:
            ids[row["id"]] = row["topic"]
            r.ok()

        # A status claiming research that does not exist is worse than no status.
        if row["status"] in {"brief", "built", "delivered"}:
            slug = re.sub(r"[^a-z0-9]+", "-", row["topic"].lower()).strip("-")
            if not list(BRIEFS.glob(f"*-{slug}.md")):
                r.warn(at, f"'{row['topic']}' is '{row['status']}' but has no brief in briefs/")
            else:
                r.ok()


# --------------------------------------------------------------------------
# links and tools
# --------------------------------------------------------------------------

def check_links(r: Report) -> None:
    for f in sorted(ROOT.rglob("*.md")):
        rel = f.relative_to(ROOT)
        if ".git" in rel.parts or rel.parts[:2] == (".claude", "worktrees"):
            continue
        for n, line in enumerate(f.read_text(encoding="utf-8").splitlines(), 1):
            for path in set(MD_PATH_RE.findall(line)):
                if (ROOT / path).exists():
                    r.ok()
                else:
                    r.error(f"{rel}:{n}", f"references '{path}' which does not exist")

    for t in sorted((ROOT / "tools").glob("*.py")):
        proc = subprocess.run([sys.executable, "-m", "py_compile", str(t)],
                              capture_output=True, text=True)
        if proc.returncode:
            r.error(str(t.relative_to(ROOT)),
                    f"does not compile: {proc.stderr.strip().splitlines()[-1]}")
        else:
            r.ok()


SUITES = {
    "briefs": check_briefs,
    "topics": check_topics,
    "links": check_links,
}


def main() -> int:
    p = argparse.ArgumentParser(description=__doc__,
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("suite", nargs="?", choices=sorted(SUITES), help="run one suite only")
    args = p.parse_args()

    r = Report()
    for name in ([args.suite] if args.suite else sorted(SUITES)):
        SUITES[name](r)

    for where, msg in r.warnings:
        print(f"warning  {where}: {msg}")
    for where, msg in r.errors:
        print(f"error    {where}: {msg}")

    n = len(r.warnings)
    if r.errors:
        print(f"\n{len(r.errors)} error(s), {n} warning(s), {r.passed} checks passed.")
        return 1
    print(f"clean — {r.passed} checks, {n} warning(s).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

