"""Extract text from a PDF with the stdlib only, and grep it.

    python3 pdftext.py <file.pdf> [pattern] [--chars N]

With a pattern, prints only windows around each match — which is what keeps a
200-page paper from landing in a conversation whole.
"""
import re
import sys
import zlib

ESCAPES = {"n": "\n", "r": "\r", "t": "\t", "b": "", "f": "", "(": "(", ")": ")", "\\": "\\"}


def unescape(s):
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == "\\" and i + 1 < len(s):
            nxt = s[i + 1]
            if nxt.isdigit():
                oct_digits = ""
                j = i + 1
                while j < len(s) and s[j].isdigit() and len(oct_digits) < 3:
                    oct_digits += s[j]
                    j += 1
                try:
                    out.append(chr(int(oct_digits, 8)))
                except ValueError:
                    pass
                i = j
                continue
            out.append(ESCAPES.get(nxt, nxt))
            i += 2
            continue
        out.append(ch)
        i += 1
    return "".join(out)


def extract(path):
    data = open(path, "rb").read()
    chunks = []
    for m in re.finditer(rb"stream\r?\n", data):
        start = m.end()
        end = data.find(b"endstream", start)
        if end == -1:
            continue
        try:
            chunks.append(zlib.decompress(data[start:end]))
        except Exception:
            continue

    text = []
    for raw in chunks:
        s = raw.decode("latin-1")
        if "Tj" not in s and "TJ" not in s:
            continue
        # PDF text operators: (string) Tj  and  [(a) -30 (b)] TJ
        for tok in re.finditer(r"\((?:\\.|[^()\\])*\)|\bTd\b|\bTD\b|\bT\*\b|\bTJ\b|\bTj\b", s):
            t = tok.group(0)
            if t.startswith("("):
                text.append(unescape(t[1:-1]))
            elif t in ("Td", "TD", "T*"):
                text.append("\n")
    out = "".join(text)
    out = re.sub(r"[ \t]+", " ", out)
    out = re.sub(r"\n{3,}", "\n\n", out)
    return out


def main():
    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    width = 600
    for a in sys.argv[1:]:
        if a.startswith("--chars"):
            width = int(a.split("=")[1]) if "=" in a else width

    text = extract(args[0])
    if len(args) < 2:
        print(text[:8000])
        print(f"\n[... {len(text)} chars total ...]")
        return

    pattern = args[1]
    hits = list(re.finditer(pattern, text, re.I))
    print(f"[{len(hits)} match(es) for {pattern!r} in {len(text)} chars]\n")
    seen = []
    for m in hits[:12]:
        a, b = max(0, m.start() - width // 2), min(len(text), m.end() + width // 2)
        if any(a < e and s < b for s, e in seen):
            continue
        seen.append((a, b))
        print("-" * 60)
        print(text[a:b].replace("\n", " ").strip())
        print()


if __name__ == "__main__":
    main()

