#!/usr/bin/env python3
"""Check a built .pptx against the house rules, by reading the file itself.

The build script can only prove it did not throw. This opens the finished artifact and
checks what actually landed in it — slide count, speaker notes, the brand palette, the
brand typefaces, and whether anything sits outside the slide.

    python3 tools/deck_qa.py build/*.pptx

Exit 1 on any error. Warnings never fail the run.
"""

from __future__ import annotations

import argparse
import re
import sys
import zipfile
from pathlib import Path

EMU_PER_IN = 914400
SLIDE_W = int(10 * EMU_PER_IN)
SLIDE_H = int(5.625 * EMU_PER_IN)

# From DEV/TechEd_Prop/ShitfWave/DESIGN.md. Anything outside this set is drift.
PALETTE = {
    "0B2A1F", "F4F2EC", "103827", "07211A", "154734", "FFB81C",
