            fill = re.search(r'<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"', spPr.group(0))
            if fill:
                own = fill.group(1).upper()
        bg = own or ground

        for rPr in re.findall(r"<a:rPr[^>]*>.*?</a:rPr>", sp, re.S):
            fg = re.search(r'<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"', rPr)
            if not fg:
                continue
            fgc = fg.group(1).upper()
            ratio = contrast(fgc, bg)
            if ratio < MIN_CONTRAST:
                problems.append(
                    f"contrast failure — #{fgc} text on #{bg} is {ratio:.1f}:1 "
                    f"(floor is {MIN_CONTRAST}:1)"
                )
    # One report per distinct pairing; a repeated label should not repeat the error.
    return sorted(set(problems))


def slide_files(z: zipfile.ZipFile) -> list[str]:
    names = [n for n in z.namelist() if re.fullmatch(r"ppt/slides/slide\d+\.xml", n)]
    return sorted(names, key=lambda n: int(re.search(r"(\d+)", n.rsplit("/", 1)[1]).group(1)))


def check_deck(path: Path, r: Report) -> None:
    name = path.name
    with zipfile.ZipFile(path) as z:
        slides = slide_files(z)

        if len(slides) != 5:
            r.error(name, f"has {len(slides)} slides — the format is exactly 5, no exceptions")
        else:
            r.ok()

        notes = [n for n in z.namelist() if re.fullmatch(r"ppt/notesSlides/notesSlide\d+\.xml", n)]
        if len(notes) != len(slides):
            r.error(name, f"{len(notes)} notes slides for {len(slides)} slides — every slide "
                          "carries talking points")
        else:
            r.ok()

        for i, sname in enumerate(slides, 1):
            at = f"{name} slide {i}"
            xml = z.read(sname).decode("utf-8", "replace")

            colors = set(m.upper() for m in re.findall(r'srgbClr val="([0-9A-Fa-f]{6})"', xml))
            stray = colors - PALETTE
            if stray:
                r.error(at, f"colours outside the brand palette: {sorted(stray)}")
            else:
                r.ok()

            faces = set(re.findall(r'typeface="([^"]+)"', xml))
            stray_f = {f for f in faces if f and not f.startswith("+") and f not in FONTS}
            if stray_f:
                r.error(at, f"typefaces outside the brand set: {sorted(stray_f)}")
            else:
                r.ok()

            # Ground colour decides which text colours are legal on this slide.
            ground = DARK_GROUND if DARK_GROUND in colors else (
                LIGHT_GROUND if LIGHT_GROUND in colors else None)
            if ground is None:
                r.warn(at, "no recognised ground colour found")
            else:
                expect_dark = (i % 2 == 1)
                if (ground == DARK_GROUND) != expect_dark:
                    r.error(at, f"ground is {'dark' if ground == DARK_GROUND else 'light'} but "
                                f"slide {i} must be {'dark' if expect_dark else 'light'} — "
                                "the dark/light alternation is the series signature")
                else:
                    r.ok()

                # Contrast has to be judged per shape, not per slide. Gold text on a green
                # plate is correct; the same gold on the bone ground measures 1.7:1 and is
                # not. A slide-wide colour set cannot tell those apart, so walk the shapes
                # and pair each text run with the background it actually sits on.
                for bad in bad_contrast(xml, ground):
                    r.error(at, bad)
                r.ok()

            # Anything drawn outside the slide is a layout bug the build cannot see.
            frames = re.findall(
                r'<a:off x="(-?\d+)" y="(-?\d+)"\s*/>\s*<a:ext cx="(\d+)" cy="(\d+)"\s*/>', xml)
            for x, y, cx, cy in frames:
                x, y, cx, cy = int(x), int(y), int(cx), int(cy)
                if x < 0 or y < 0:
                    r.error(at, f"element starts off-slide at ({x/EMU_PER_IN:.2f}in, "
                                f"{y/EMU_PER_IN:.2f}in)")
                elif x + cx > SLIDE_W + 1000 or y + cy > SLIDE_H + 1000:
                    r.error(at, f"element runs past the slide edge — right "
                                f"{(x+cx)/EMU_PER_IN:.2f}in, bottom {(y+cy)/EMU_PER_IN:.2f}in "
                                f"(slide is 10.00 × 5.63in)")
                else:
                    r.ok()

            if not frames:
                r.warn(at, "no positioned elements parsed — check the QA pattern still matches")


def main() -> int:
    p = argparse.ArgumentParser(description=__doc__,
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("decks", nargs="+", help="one or more .pptx files")
    args = p.parse_args()

    r = Report()
    for f in args.decks:
        path = Path(f)
        if not path.exists():
            r.error(str(path), "does not exist")
            continue
        check_deck(path, r)

    for where, msg in r.warnings:
        print(f"warning  {where}: {msg}")
    for where, msg in r.errors:
        print(f"error    {where}: {msg}")

    if r.errors:
        print(f"\n{len(r.errors)} error(s), {len(r.warnings)} warning(s), {r.passed} checks passed.")
        return 1
    print(f"clean — {r.passed} checks, {len(r.warnings)} warning(s).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

