input.content:
/**
 * Direction A — Sequence rail.
 *
 * THESIS: a five-minute talk to a half-attending room should never leave anyone unsure
 * where they are in the argument. The deck's own structure is drawn on every slide and
 * the current step is lit. Refuses the category default, which is a slide number in the
 * corner that nobody reads.
 *
 * OWN-WORLD: the department's palette and type, unchanged. What changes is that the
 * argument becomes furniture: a rail of five stations under the header, the live one
 * filled gold and named, the rest hairline ticks. Recognisable with all content removed.
 *
 * FIRST VIEWPORT: rail across the top third, the live station carrying its name. One wide
 * type column beneath it. No stat plate, no cards; weight and scale carry the hierarchy.
 *
 * RISK: the rail costs vertical space on every slide, so long footnotes get tighter. If a
 * deck needs a dense chart and a long caveat, this is the wrong direction for it.
 */

const pptxgen = require("pptxgenjs");
const {
  barPair, noiseBand, stateSplit, rect, microLabel, C, F, W, H, M,
} = require("../_kit");

const STATIONS = ["hook", "problem", "insight", "apply", "takeaway"];
const RAIL_Y = 0.92;

/** The argument, drawn. Five stations, the live one named and filled. */
function rail(s, { n, dark }) {
  const ink = dark ? C.MINT : C.GRAY_INK;
  const live = dark ? C.GOLD : C.GOLD_INK;
  const dim = dark ? C.MID_GREEN : C.BONE_LINE;
  const railW = W - M * 2;
  const step = railW / STATIONS.length;

  rect(s, { x: M, y: RAIL_Y + 0.20, w: railW, h: 0.01, fill: { color: dim } });

  STATIONS.forEach((name, i) => {
    const on = i === n - 1;
    const x = M + i * step;
    rect(s, {
      x, y: on ? RAIL_Y + 0.10 : RAIL_Y + 0.15,
      w: on ? step - 0.14 : 0.055,
      h: on ? 0.20 : 0.11,
      fill: { color: on ? live : dim },
    });
    if (on) {
      microLabel(s, name, { x, y: RAIL_Y + 0.36, w: step, color: live, size: 9 });
    }
  });

  // Position without a fraction: the rail already shows extent, so the number would
  // be saying the same thing twice.
  microLabel(s, `step ${n}`, {
    x: W - M - 2, y: RAIL_Y + 0.36, w: 2, color: ink, align: "right", size: 8,
  });
}

function slide(pres, { dark, topic, n }) {
  const s = pres.addSlide();
  s.background = { color: dark ? C.GROUND_DARK : C.GROUND_LIGHT };
  const ink = dark ? C.MINT : C.GRAY_INK;
  const accent = dark ? C.GOLD : C.GOLD_INK;

  microLabel(s, "5 slides · 5 minutes", { x: M, y: 0.34, w: 4.2, color: accent });
