function rail(s, { n, dark }) {
  const ink = dark ? C.MINT : C.GRAY_INK;
  const live = dark ? C.GOLD : C.GOLD_INK;
  const dim = dark ? C.MID_GREEN : C.BONE_LINE;
  const railW = W - M * 2;
  const step = railW / STATIONS.length;

  rect(s, { x: M, y: RAIL_Y + 0.20, w: railW, h: 0.01, fill: { color: dim } });

  STATIONS.forEach((name, i) => {
    const on = i === n - 1;
    const x = M + i * step;
    rect(s, {
      x, y: on ? RAIL_Y + 0.10 : RAIL_Y + 0.15,
      w: on ? step - 0.14 : 0.055,
      h: on ? 0.20 : 0.11,
      fill: { color: on ? live : dim },
    });
    if (on) {
      microLabel(s, name, { x, y: RAIL_Y + 0.36, w: step, color: live, size: 9 });
    }
  });

  // Position without a fraction: the rail already shows extent, so the number would
  // be saying the same thing twice.
  microLabel(s, `step ${n}`, {
    x: W - M - 2, y: RAIL_Y + 0.36, w: 2, color: ink, align: "right", size: 8,
  });
}

function slide(pres, { dark, topic, n }) {
  const s = pres.addSlide();
  s.background = { color: dark ? C.GROUND_DARK : C.GROUND_LIGHT };
