  microLabel(s, topic, { x: W - M - 4.2, y: 0.34, w: 4.2, color: ink, align: "right" });
  rail(s, { n, dark });

  rect(s, { x: M, y: H - 0.52, w: W - M * 2, h: 0.01, fill: { color: dark ? C.GOLD_INK : C.BONE_LINE } });
  microLabel(s, "Baylor Athletics · Applied Performance", {
    x: M, y: H - 0.44, w: 6, color: ink, size: 8,
  });
  return s;
}

const TOP = 1.86;   // everything hangs below the rail

function visuals(s, { x, y, w, dark }) {
  return {
    x, y, w, dark,
    bars: (o) => barPair(s, { x, y, w: w - 1.0, dark, ...o }),
