/**
 * Direction B — Split field.
 *
 * THESIS: every slide shows the claim and its evidence at the same time, so the room can
 * check one against the other without waiting. Refuses the category default of a headline
 * slide followed by a proof slide, where the two never share a viewport.
 *
 * OWN-WORLD: the department's palette and type, unchanged. The dark/light alternation
 * moves inside the slide: a forest panel holds the claim, a bone field holds the evidence,
 * divided by a hard vertical with a gold rule on it. Recognisable with all content removed.
 *
 * FIRST VIEWPORT: forest claim panel on the left 38%, bone evidence field on the right,
 * one gold hairline on the seam. The display line sits in the dark panel.
 *
 * RISK: the claim panel is narrow, so a long head wraps hard. Topics whose claim needs a
 * full sentence will fight this direction.
 */

const pptxgen = require("pptxgenjs");
const {
  barPair, noiseBand, stateSplit, rect, microLabel, C, F, W, H, M,
} = require("../_kit");

const SEAM = W * 0.38;      // where the claim panel ends
const PAD = 0.42;
const TOP = 1.16;

function slide(pres, { topic, n, label }) {
  const s = pres.addSlide();
  s.background = { color: C.GROUND_LIGHT };

  // The dark field is a drawn panel rather than a slide background, which is what lets
  // both grounds share one viewport.
  rect(s, { x: 0, y: 0, w: SEAM, h: H, fill: { color: C.GROUND_DARK } });
  rect(s, { x: SEAM, y: 0, w: 0.028, h: H, fill: { color: C.GOLD } });

  microLabel(s, label, { x: PAD, y: 0.44, w: SEAM - PAD * 2, color: C.GOLD });
  microLabel(s, topic, {
    x: SEAM + PAD, y: 0.44, w: W - SEAM - PAD * 2, color: C.GRAY_INK, align: "right",
  });

  rect(s, { x: SEAM + PAD, y: H - 0.60, w: W - SEAM - PAD * 2, h: 0.008, fill: { color: C.BONE_LINE } });
  microLabel(s, "Baylor Athletics · Applied Performance", {
    x: SEAM + PAD, y: H - 0.50, w: 4.4, color: C.GRAY_INK, size: 8,
  });
  microLabel(s, `${n} / 5`, {
    x: W - PAD - 1.4, y: H - 0.50, w: 1.4, color: C.GOLD_INK, align: "right", size: 8,
  });
  return s;
}

/** Claim side: the sentence the room is being asked to accept. */
function claim(s, text, { size = 21, display = false } = {}) {
  s.addText(text, {
    x: PAD, y: TOP, w: SEAM - PAD * 2, h: 3.1,
    fontSize: size, fontFace: display ? F.DISPLAY : F.COND_MED,
    color: C.WHITE, align: "left", valign: "top", margin: 0,
    lineSpacingMultiple: display ? 1.16 : 1.06,
  });
}

function visuals(s, { x, y, w, dark }) {
  return {
    x, y, w, dark,
    bars: (o) => barPair(s, { x, y, w, dark, ...o }),
    band: (o) => noiseBand(s, { x, y, w, dark, bandLabel: o.label, ...o }),
    split: (o) => stateSplit(s, { x, y, w, dark, ...o }),
  };
}

async function buildDeck(d, outPath) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Baylor Athletics · Applied Performance";
  pres.title = `${d.title} — 5 Slides in 5 Minutes (split field)`;

  const EX = SEAM + PAD;                    // evidence-side origin
  const EW = W - SEAM - PAD * 2;            // evidence-side width

  // 1 — hook
  {
    const s = slide(pres, { topic: d.topic, n: 1, label: "the hook" });
    s.addText(`${d.hook.display}\n${d.hook.accent}`, {
      x: PAD, y: TOP, w: SEAM - PAD * 2, h: 3.0, fontSize: 34, fontFace: F.DISPLAY,
      color: C.WHITE, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.18,
    });
    s.addText(d.hook.sub, {
      x: EX, y: TOP + 0.10, w: EW, h: 2.0, fontSize: 15, fontFace: F.BODY_LIGHT,
      color: C.GRAY_INK, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.24,
    });
    s.addNotes(d.hook.notes);
  }

  // 2 — problem
  {
    const s = slide(pres, { topic: d.topic, n: 2, label: "the problem" });
    claim(s, d.problem.head);
    s.addText(d.problem.stat, {
      x: EX, y: TOP - 0.16, w: EW, h: 1.0, fontSize: 50, fontFace: F.COND, bold: true,
      color: C.GOLD_INK, align: "left", valign: "top", margin: 0,
    });
    s.addText(d.problem.statCaption, {
      x: EX, y: TOP + 0.92, w: EW, h: 0.9, fontSize: 11, fontFace: F.BODY_LIGHT,
      color: C.GRAY_INK, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.14,
    });
    rect(s, { x: EX, y: TOP + 1.92, w: EW, h: 0.008, fill: { color: C.BONE_LINE } });
    s.addText(d.problem.body, {
      x: EX, y: TOP + 2.06, w: EW, h: 1.6, fontSize: 11.5, fontFace: F.BODY_LIGHT,
      color: C.GRAY_INK, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.2,
    });
    s.addNotes(d.problem.notes);
  }

  // 3 — insight. The evidence side carries the chart on the bone ground.
  {
    const s = slide(pres, { topic: d.topic, n: 3, label: "the insight" });
    claim(s, d.insight.head);
    const bottom = d.insight.visual(visuals(s, { x: EX, y: TOP + 0.10, w: EW, dark: false }));
    if (d.insight.foot) {
      const fy = Math.max(bottom + 0.18, 3.60);
      s.addText(d.insight.foot, {
        x: EX, y: fy, w: EW, h: H - 0.70 - fy, fontSize: 10, fontFace: F.BODY_LIGHT,
        color: C.GRAY_INK, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.12,
      });
    }
    s.addNotes(d.insight.notes);
  }

  // 4 — apply
  {
    const s = slide(pres, { topic: d.topic, n: 4, label: "on monday" });
    claim(s, d.apply.head);
    s.addText(d.apply.rule, {
      x: PAD, y: H - 2.05, w: SEAM - PAD * 2, h: 1.3, fontSize: 11.5, fontFace: F.BODY_LIGHT,
      color: C.MINT, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.16,
    });
    let ry = TOP + 0.02;
    d.apply.columns.forEach((c) => {
      microLabel(s, c.who, { x: EX, y: ry, w: EW, color: C.GOLD_INK, size: 8 });
      s.addText(c.what, {
        x: EX, y: ry + 0.24, w: EW, h: 0.66, fontSize: 10.5, fontFace: F.BODY_LIGHT,
        color: C.GREEN, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.1,
      });
      ry += 0.94;
    });
    s.addNotes(d.apply.notes);
  }

  // 5 — takeaway
  {
    const s = slide(pres, { topic: d.topic, n: 5, label: "the one thing" });
    claim(s, d.takeaway.oneThing, { size: 18 });
    microLabel(s, "for the room", { x: EX, y: TOP + 0.10, w: EW, color: C.GOLD_INK });
    s.addText(d.takeaway.question, {
      x: EX, y: TOP + 0.46, w: EW, h: 1.4, fontSize: 15, fontFace: F.BODY_LIGHT,
      color: C.GREEN, italic: true, align: "left", valign: "top", margin: 0,
      lineSpacingMultiple: 1.2,
    });
    s.addNotes(d.takeaway.notes);
  }

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

module.exports = { buildDeck, name: "split-field" };

