/**
 * Direction C — Annotated evidence.
 *
 * THESIS: the evidence is the slide and the argument is written in the margin around it,
 * the way a figure works in a paper. Refuses the category default where a chart is
 * decoration underneath a headline that already told you the answer.
 *
 * OWN-WORLD: the department's palette and type, unchanged. Every slide is a numbered
 * figure with a caption: a plate holding the evidence, a hairline margin rule, and short
 * annotations set against it. Recognisable with all content removed by the figure number
 * and the caption rule.
 *
 * FIRST VIEWPORT: the figure plate fills the centre. A tracked FIG. label sits top-left of
 * it, the caption runs under the rule beneath, and the argument is two short margin notes.
 *
 * RISK: it asks the room to read a figure in five minutes. For a topic whose evidence is
 * one number, the apparatus is heavier than the content it carries.
 */

const pptxgen = require("pptxgenjs");
const {
  barPair, noiseBand, stateSplit, rect, microLabel, C, F, W, H, M,
} = require("../_kit");

const PAD = 0.62;
const FIG_TOP = 1.30;

function slide(pres, { dark, topic, n }) {
  const s = pres.addSlide();
  s.background = { color: dark ? C.GROUND_DARK : C.GROUND_LIGHT };
  const ink = dark ? C.MINT : C.GRAY_INK;
  const accent = dark ? C.GOLD : C.GOLD_INK;

  microLabel(s, `fig. ${n} of 5`, { x: PAD, y: 0.40, w: 3, color: accent });
  microLabel(s, topic, { x: W - PAD - 4.6, y: 0.40, w: 4.6, color: ink, align: "right" });
  microLabel(s, "Baylor Athletics · Applied Performance", {
    x: PAD, y: H - 0.46, w: 6, color: ink, size: 8,
  });
  return s;
}

/** The figure plate. Everything a slide asserts sits inside or beside this. */
function plate(s, { x, y, w, h, dark }) {
  rect(s, { x, y, w, h, fill: { color: dark ? C.PANEL : C.WHITE } });
  rect(s, { x, y, w, h: 0.028, fill: { color: dark ? C.GOLD : C.GOLD_INK } });
  return { x, y, w, h };
}

/** Caption under a rule, the way a figure legend sits under its figure. */
function caption(s, text, { x, y, w, dark }) {
  rect(s, { x, y, w, h: 0.008, fill: { color: dark ? C.GOLD_INK : C.BONE_LINE } });
  s.addText(text, {
    x, y: y + 0.12, w, h: H - 0.62 - (y + 0.12), fontSize: 10.5, fontFace: F.BODY_LIGHT,
    color: dark ? C.MINT : C.GRAY_INK, align: "left", valign: "top",
    margin: 0, lineSpacingMultiple: 1.14,
  });
}

function visuals(s, { x, y, w, dark }) {
  return {
    x, y, w, dark,
    bars: (o) => barPair(s, { x, y, w, dark, ...o }),
    band: (o) => noiseBand(s, { x, y, w, dark, bandLabel: o.label, ...o }),
    split: (o) => stateSplit(s, { x, y, w, dark, ...o }),
  };
}

async function buildDeck(d, outPath) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Baylor Athletics · Applied Performance";
  pres.title = `${d.title} — 5 Slides in 5 Minutes (annotated evidence)`;

  const FW = W - PAD * 2;

  // 1 — hook. The figure is the claim itself, set at display scale on the plate.
  {
    const s = slide(pres, { dark: true, topic: d.topic, n: 1 });
    plate(s, { x: PAD, y: FIG_TOP, w: FW, h: 2.30, dark: true });
    s.addText(d.hook.display, {
      x: PAD + 0.34, y: FIG_TOP + 0.30, w: FW - 0.68, h: 0.86, fontSize: 40,
      fontFace: F.DISPLAY, color: C.WHITE, align: "left", valign: "top", margin: 0,
    });
    s.addText(d.hook.accent, {
      x: PAD + 0.34, y: FIG_TOP + 1.18, w: FW - 0.68, h: 0.86, fontSize: 40,
      fontFace: F.DISPLAY, color: C.GOLD, align: "left", valign: "top", margin: 0,
    });
    caption(s, d.hook.sub, { x: PAD, y: FIG_TOP + 2.56, w: FW, dark: true });
    s.addNotes(d.hook.notes);
  }

  // 2 — problem. The number is the figure; the argument is the margin note beside it.
  {
    const s = slide(pres, { dark: false, topic: d.topic, n: 2 });
    const pw = FW * 0.42;
    plate(s, { x: PAD, y: FIG_TOP, w: pw, h: 2.10, dark: false });
    s.addText(d.problem.stat, {
      x: PAD + 0.28, y: FIG_TOP + 0.36, w: pw - 0.56, h: 1.0, fontSize: 46,
      fontFace: F.COND, bold: true, color: C.GOLD_INK,
      align: "left", valign: "top", margin: 0,
    });
    s.addText(d.problem.statCaption, {
      x: PAD + 0.28, y: FIG_TOP + 1.34, w: pw - 0.56, h: 0.7, fontSize: 9.5,
      fontFace: F.BODY_LIGHT, color: C.GRAY_INK, align: "left", valign: "top",
      margin: 0, lineSpacingMultiple: 1.1,
    });

    const mx = PAD + pw + 0.44;
    const mw = FW - pw - 0.44;
    s.addText(d.problem.head, {
      x: mx, y: FIG_TOP - 0.04, w: mw, h: 0.8, fontSize: 24, fontFace: F.COND_MED,
      color: C.GREEN, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 0.98,
    });
    s.addText(d.problem.body, {
      x: mx, y: FIG_TOP + 0.86, w: mw, h: 2.3, fontSize: 11, fontFace: F.BODY_LIGHT,
      color: C.GRAY_INK, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.2,
    });
    s.addNotes(d.problem.notes);
  }

  // 3 — insight. The real figure, on its plate, with the head above and legend below.
  {
    const s = slide(pres, { dark: true, topic: d.topic, n: 3 });
    s.addText(d.insight.head, {
      x: PAD, y: 0.80, w: FW, h: 0.52, fontSize: 24, fontFace: F.COND_MED,
      color: C.WHITE, align: "left", valign: "top", margin: 0,
    });
    const h = 2.24;
    plate(s, { x: PAD, y: FIG_TOP + 0.10, w: FW, h, dark: true });
    const bottom = d.insight.visual(
      visuals(s, { x: PAD + 0.34, y: FIG_TOP + 0.62, w: FW - 0.68, dark: true }));
    if (d.insight.foot) {
      caption(s, d.insight.foot, {
        x: PAD, y: Math.max(bottom + 0.16, FIG_TOP + h + 0.24), w: FW, dark: true,
      });
    }
    s.addNotes(d.insight.notes);
  }

  // 4 — apply. Each specialty is its own small plate in a strip.
  {
    const s = slide(pres, { dark: false, topic: d.topic, n: 4 });
    s.addText(d.apply.head, {
      x: PAD, y: 0.80, w: FW, h: 0.52, fontSize: 24, fontFace: F.COND_MED,
      color: C.GREEN, align: "left", valign: "top", margin: 0,
    });
    const cols = d.apply.columns;
    const gap = 0.24;
    const cw = (FW - gap * (cols.length - 1)) / cols.length;
    cols.forEach((c, i) => {
      const cx = PAD + i * (cw + gap);
      plate(s, { x: cx, y: FIG_TOP + 0.10, w: cw, h: 1.98, dark: false });
      microLabel(s, c.who, { x: cx + 0.16, y: FIG_TOP + 0.26, w: cw - 0.32, color: C.GOLD_INK, size: 8 });
      s.addText(c.what, {
        x: cx + 0.16, y: FIG_TOP + 0.58, w: cw - 0.32, h: 1.34, fontSize: 10,
        fontFace: F.BODY_LIGHT, color: C.GREEN, align: "left", valign: "top",
        margin: 0, lineSpacingMultiple: 1.12,
      });
    });
    caption(s, d.apply.rule, { x: PAD, y: FIG_TOP + 2.30, w: FW, dark: false });
    s.addNotes(d.apply.notes);
  }

  // 5 — takeaway
  {
    const s = slide(pres, { dark: true, topic: d.topic, n: 5 });
    plate(s, { x: PAD, y: FIG_TOP, w: FW, h: 1.96, dark: true });
    s.addText(d.takeaway.oneThing, {
      x: PAD + 0.34, y: FIG_TOP + 0.34, w: FW - 0.68, h: 1.4, fontSize: 21,
      fontFace: F.COND_MED, color: C.WHITE, align: "left", valign: "top",
      margin: 0, lineSpacingMultiple: 1.08,
    });
    caption(s, d.takeaway.question, { x: PAD, y: FIG_TOP + 2.20, w: FW, dark: true });
    s.addNotes(d.takeaway.notes);
  }

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

module.exports = { buildDeck, name: "annotated" };

