/**
 * Build one deck in every design direction, for comparison.
 *
 *     node decks/build-variants.js [deck-slug] [outDir]
 *
 * Same content, same brand, different structure. The point of the data/renderer split is
 * that this costs one file per direction rather than a rewrite of five decks.
 */
const fs = require("fs");
const path = require("path");

const deckFile = process.argv[2] || "data-to-decision";
const OUT = path.resolve(process.argv[3] || path.join(__dirname, "..", "build", "variants"));

const d = require(path.join(__dirname, `${deckFile}.js`));

const VARIANTS = [
  ["A", require("./variants/sequence-rail")],
  ["B", require("./variants/split-field")],
  ["C", require("./variants/annotated")],
];

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  let failed = 0;
  for (const [letter, v] of VARIANTS) {
    const out = path.join(OUT, `${d.slug}__${letter}-${v.name}.pptx`);
    try {
      await v.buildDeck(d, out);
      console.log(`ok    ${path.basename(out)}  (${(fs.statSync(out).size / 1024).toFixed(0)} KB)`);
    } catch (err) {
      failed += 1;
      console.error(`FAIL  ${v.name}: ${err.message}`);
    }
  }
  console.log(`\n${VARIANTS.length - failed}/${VARIANTS.length} directions built into ${OUT}`);
  process.exit(failed ? 1 : 0);
})();

