/**
 * Build every deck in this directory.
 *
 *     node decks/build-all.js [outDir]
 *
 * Output defaults to build/, which is gitignored — the narrative in these files is the
 * source of truth and the .pptx is regenerated from it, never edited in place and
 * committed back.
 */
const fs = require("fs");
const path = require("path");
const { buildDeck } = require("./_kit");

const OUT = path.resolve(process.argv[2] || path.join(__dirname, "..", "build"));

const specs = fs
  .readdirSync(__dirname)
  .filter((f) => f.endsWith(".js") && !f.startsWith("_") && f !== "build-all.js")
  .sort();

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  let failed = 0;

  for (const file of specs) {
    const d = require(path.join(__dirname, file));
    const out = path.join(OUT, `${d.slug}_5Slides5Minutes.pptx`);
    try {
      await buildDeck(d, out);
      const kb = (fs.statSync(out).size / 1024).toFixed(0);
      console.log(`ok    ${path.basename(out)}  (${kb} KB)`);
    } catch (err) {
      failed += 1;
      console.error(`FAIL  ${file}: ${err.message}`);
    }
  }

  console.log(`\n${specs.length - failed}/${specs.length} decks built into ${OUT}`);
  process.exit(failed ? 1 : 0);
})();

