function stateSplit(s, { x, y, w, dark, kept, lost }) {
  const cardW = (w - 0.5) / 2;
  const pairs = [
    { ...kept, ok: true, cx: x },
    { ...lost, ok: false, cx: x + cardW + 0.5 },
  ];
  pairs.forEach((p) => {
    rect(s, {
      x: p.cx, y, w: cardW, h: 1.62,
      fill: { color: dark ? C.PANEL : C.WHITE },
      line: p.ok ? { none: true } : { color: dark ? C.GOLD : C.GOLD_INK, width: 1.5 },
      shadow: dark ? undefined : shadow(),
    });
    microLabel(s, p.tag, {
      x: p.cx + 0.22, y: y + 0.18, w: cardW - 0.44,
      color: p.ok ? (dark ? C.MINT : C.GRAY_INK) : (dark ? C.GOLD : C.GOLD_INK),
    });
    s.addText(p.head, {
      x: p.cx + 0.22, y: y + 0.5, w: cardW - 0.44, h: 0.45, fontSize: 19,
      fontFace: F.COND_MED, color: dark ? C.WHITE : C.GREEN,
      align: "left", valign: "top", margin: 0,
    });
    s.addText(p.body, {
      x: p.cx + 0.22, y: y + 0.96, w: cardW - 0.44, h: 0.56, fontSize: 11.5,
      fontFace: F.BODY_LIGHT, color: dark ? C.MINT : C.GRAY_INK,
      align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.12,
    });
  });
  return y + 1.62;
}

