/**
 * Build every deck in this directory.
 *
 *     node decks/build-all.js [outDir]
 *
 * Output defaults to build/, which is gitignored — the narrative in these files is the
 * source of truth and the .pptx is regenerated from it, never edited in place and
 * committed back.
 */
const fs = require("fs");
const path = require("path");

// Which design direction to render in. The default is the editorial column in _kit.js;
// `--direction split-field` renders every deck through decks/variants/split-field.js.
// Content is direction-agnostic, so this is the only switch there is.
const argv = process.argv.slice(2);
const dirIdx = argv.indexOf("--direction");
const direction = dirIdx === -1 ? null : argv[dirIdx + 1];
if (dirIdx !== -1) argv.splice(dirIdx, 2);

const { buildDeck } = direction
  ? require(`./variants/${direction}`)
  : require("./_kit");

const OUT = path.resolve(argv[0] || path.join(__dirname, "..", "build"));

// Deck content only. `build-` files are scripts whose top-level code runs on require,
// so including build-variants.js here made every base build silently run the variant
// build too, interleaving its output with this one.
const specs = fs
  .readdirSync(__dirname)
  .filter((f) => f.endsWith(".js") && !f.startsWith("_") && !f.startsWith("build-"))
  .sort();

(async () => {
  fs.mkdirSync(OUT, { recursive: true });
  let failed = 0;

  for (const file of specs) {
    const d = require(path.join(__dirname, file));
    const out = path.join(OUT, `${d.slug}_5Slides5Minutes.pptx`);
    try {
      await buildDeck(d, out);
      const kb = (fs.statSync(out).size / 1024).toFixed(0);
      console.log(`ok    ${path.basename(out)}  (${kb} KB)`);
    } catch (err) {
      failed += 1;
      console.error(`FAIL  ${file}: ${err.message}`);
    }
  }

  console.log(`\n${specs.length - failed}/${specs.length} decks built into ${OUT}`);
  process.exit(failed ? 1 : 0);
})();

