def parse_shapes(xml: str):
    """Every <p:sp> we emit: a rect, a text box, or a text box with a fill."""
    out = []
    for sp in re.findall(r"<p:sp>.*?</p:sp>", sp_split(xml), re.S):
        pos = re.search(
            r'<a:off x="(-?\d+)" y="(-?\d+)"\s*/>\s*<a:ext cx="(\d+)" cy="(\d+)"\s*/>', sp)
        if not pos:
            continue
        x, y, cx, cy = (int(g) / EMU for g in pos.groups())

        spPr = re.search(r"<p:spPr>.*?</p:spPr>", sp, re.S)
        fill = None
        if spPr:
            m = re.search(r'<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"', spPr.group(0))
            if m:
                fill = m.group(1)

        body = re.search(r"<p:txBody>.*?</p:txBody>", sp, re.S)
        paras = []
        if body:
            for p in re.findall(r"<a:p>.*?</a:p>", body.group(0), re.S):
                runs = []
                for r in re.findall(r"<a:r>.*?</a:r>", p, re.S):
                    t = "".join(re.findall(r"<a:t>(.*?)</a:t>", r, re.S))
                    if not t:
                        continue
                    rPr = re.search(r"<a:rPr[^>]*>", r)
                    attrs = rPr.group(0) if rPr else ""
                    sz = re.search(r'sz="(\d+)"', attrs)
                    col = re.search(r'<a:solidFill><a:srgbClr val="([0-9A-Fa-f]{6})"', r)
                    tf = re.search(r'typeface="([^"]+)"', r)
                    runs.append({
                        "text": html.unescape(t),
                        "size": (int(sz.group(1)) / 100) if sz else 12.0,
                        "color": col.group(1) if col else "000000",
                        "face": tf.group(1) if tf else "",
                        "bold": 'b="1"' in attrs,
                        "italic": 'i="1"' in attrs,
                    })
                if runs:
                    algn = re.search(r'algn="(\w+)"', p)
                    paras.append({"runs": runs, "align": algn.group(1) if algn else "l"})

        anchor = "t"
        if body:
            a = re.search(r'anchor="(\w+)"', body.group(0))
            if a:
                anchor = a.group(1)

        out.append({"x": x, "y": y, "w": cx, "h": cy,
                    "fill": fill, "paras": paras, "anchor": anchor})
    return out


def sp_split(xml: str) -> str:
    return xml

