/**
 * THESIS: a five-minute argument is a set of drawings, not a set of headlines. Every
 *   sheet dimensions its evidence the way a shop drawing dimensions a part, so the room
 *   reads a measurement before it reads a claim. Refuses the category default — a title
 *   over a picture over a caption — on all five sheets, not just the one with a chart.
 * OWN-WORLD: a blueprint set. Deep forest sheet, mid-green frame and rules at drafting
 *   weight, 45° section hatch in mint, condensed all-caps annotation tracked wide, a
 *   ruled notes row across the foot and a three-cell title block under it. Baylor gold
 *   is spent once per sheet, on the one dimension that carries the argument.
 *   Recognisable with every word removed.
 * STORY: the room opens a drawing set, finds the question on the cover, the measured
 *   problem on sheet 2, the noise floor dimensioned on sheet 3, the schedule of what
 *   changes on sheet 4, and one line to carry out on sheet 5.
 * FIRST VIEWPORT: sheet 1 is a cover — the display line at plan scale on the left, scope
 *   and audience ruled into cells on the right, the drawing's name in the title block.
 * FORM: the tolerance drawing, extended from one sheet to the set. Seed key 24b50457.
 * FINISH: unreviewed and undocumented is unfinished; this build ends with the finish
 *   review, the verdict, and DESIGN.md
 *
 * A direction is a kit, not a rewrite of five decks. Content files declare what kind of
 * visual they need — bars, a noise band, a two-state split — and this file decides how
 * that gets drawn. Nothing here reaches into a deck's narrative.
 */
const pptxgen = require("pptxgenjs");
const { C, F } = require("../_kit");

// ── the sheet ──────────────────────────────────────────────────────────────────
const W = 10, H = 5.625;
const HAIR = 0.012;
const B = { x0: 0.30, y0: 0.26, x1: 9.70, y1: 5.36 };
const PAD = 0.46;
const HEAD_RULE = 0.82;
const DRAW_TOP = 0.94;
const DRAW_BOT = 3.86;
const NOTE_RULE = 3.92;
const TB = 4.60;                    // title block
const DIV_A = 5.55, DIV_B = 7.70;   // the sheet's two vertical divisions

// Every straight line on these sheets is a filled rect. pptxgenjs 4 writes a 1pt
// #333333 outline onto any shape that asks for no border, so nothing here asks for one.
function line(s, { x, y, w, h, color }) {
  s.addShape("rect", { x, y, w, h, fill: { color }, line: { color, width: 0.25 } });
}
const hrule = (s, x, y, w, color) => line(s, { x, y, w, h: HAIR, color });
const vrule = (s, x, y, h, color, t = HAIR) => line(s, { x, y, w: t, h, color });

/** A drafting arrowhead. `dir` is the direction it points. */
function arrow(s, { x, y, dir, color, size = 0.12 }) {
  s.addShape("triangle", {
    x: x - size / 2, y: y - size / 2, w: size, h: size,
    fill: { color }, line: { color, width: 0.25 },
    rotate: dir === "left" ? 270 : 90,
  });
}

/** 45° section hatch, clipped to the rect. Drafting says "this region is excluded". */
function hatch(s, { x, y, w, h, step = 0.18, color, width = 0.5 }) {
  for (let k = -h; k < w; k += step) {
    const t0 = Math.max(-k, 0);
    const t1 = Math.min(w - k, h);
    if (t1 - t0 < 0.02) continue;
    s.addShape("line", {
      x: x + k + t0, y: y + t0, w: t1 - t0, h: t1 - t0,
      line: { color, width },
    });
  }
}

/**
 * A drafting centreline: long dash, short dash, repeat.
 *
 * Heavier and brighter than any adjustable line on the sheet, on purpose. A datum is
 * measured and a threshold is chosen, and that distinction cannot rest on dash rhythm,
 * which does not survive a projector.
 */
function centreline(s, { x, y0, y1, color }) {
  let y = y0;
  let long = true;
  while (y < y1) {
    const seg = Math.min(long ? 0.17 : 0.05, y1 - y);
    vrule(s, x, y, seg, color, 0.020);
    y += seg + 0.055;
    long = !long;
  }
}

function label(s, text, { x, y, w, color, size = 8, align = "left", face = F.COND, h = 0.20 }) {
  s.addText(text.toUpperCase(), {
    x, y, w, h, fontSize: size, fontFace: face, color, align,
    charSpacing: 1.1, valign: "top", margin: 0,
  });
}

function body(s, text, { x, y, w, h, color = C.MINT, size = 10.5, italic = false }) {
  s.addText(text, {
    x, y, w, h, fontSize: size, fontFace: F.BODY_LIGHT, color, italic,
    valign: "top", margin: 0, lineSpacingMultiple: 1.12,
  });
}

/**
 * The chrome every sheet in the set shares: frame, header rule, notes rule, title
 * block. Drawn first so a sheet's own content sits on top of it, and identical on all
 * five so the set reads as one drawing rather than five slides.
 */
function sheet(pres, d, { n, caption, title }) {
  const s = pres.addSlide();
  s.background = { color: C.GROUND_DARK };

  hrule(s, B.x0, B.y0, B.x1 - B.x0, C.MID_GREEN);
  hrule(s, B.x0, B.y1, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, B.x0, B.y0, B.y1 - B.y0, C.MID_GREEN);
  vrule(s, B.x1, B.y0, B.y1 - B.y0, C.MID_GREEN);
  hrule(s, B.x0, HEAD_RULE, B.x1 - B.x0, C.MID_GREEN);

  label(s, caption, { x: PAD, y: 0.46, w: 5.0, color: C.MINT, size: 9 });
  label(s, `${d.topic} · 5 Slides in 5 Minutes`,
    { x: 5.90, y: 0.46, w: 3.66, color: C.MINT, size: 9, align: "right" });

  // The foot is one structure: the notes rule and the title block share two divisions.
  hrule(s, B.x0, NOTE_RULE, B.x1 - B.x0, C.MID_GREEN);
  vrule(s, DIV_A, NOTE_RULE, B.y1 - NOTE_RULE, C.MID_GREEN);
  vrule(s, DIV_B, NOTE_RULE, B.y1 - NOTE_RULE, C.MID_GREEN);
  hrule(s, B.x0, TB, B.x1 - B.x0, C.MID_GREEN);

  label(s, "Title", { x: PAD, y: TB + 0.05, w: 2.0, color: C.MINT, size: 7.5 });
  s.addText(title, {
    x: PAD, y: TB + 0.19, w: 5.02, h: 0.54, fontSize: 21, fontFace: F.COND_MED,
    color: C.WHITE, valign: "top", margin: 0, lineSpacingMultiple: 1.02,
  });

  label(s, "Subject", { x: 5.71, y: TB + 0.05, w: 1.9, color: C.MINT, size: 7.5 });
  s.addText(d.topic, {
    x: 5.71, y: TB + 0.19, w: 1.9, h: 0.22, fontSize: 10, fontFace: F.COND_MED,
    color: C.MINT_SOFT, valign: "top", margin: 0,
  });
  s.addText("Baylor Athletics · Applied Performance", {
    x: 5.71, y: TB + 0.42, w: 1.9, h: 0.20, fontSize: 7.5, fontFace: F.BODY_LIGHT,
    color: C.MINT, valign: "top", margin: 0,
  });

  label(s, "Sheet", { x: 7.86, y: TB + 0.05, w: 1.7, color: C.MINT, size: 7.5 });
  s.addText(`${n} / 5`, {
    x: 7.86, y: TB + 0.19, w: 1.7, h: 0.26, fontSize: 13, fontFace: F.COND,
    color: C.MINT_SOFT, valign: "top", margin: 0, charSpacing: 1,
  });

  return s;
}

/** The three general-note cells, on the sheet's own divisions. */
function notes(s, cells) {
  const cols = [
    { x: PAD, w: 4.93, size: 9.5 },
    { x: 5.71, w: 1.83, size: 9 },
    { x: 7.86, w: 1.68, size: 8.5 },
  ];
  cells.forEach((text, i) => {
    if (!text) return;
    const c = cols[i];
    label(s, `Note ${i + 1}`, { x: c.x, y: NOTE_RULE + 0.05, w: 1.2, color: C.MINT_SOFT, size: 8 });
    body(s, text, { x: c.x, y: NOTE_RULE + 0.19, w: c.w, h: 0.46, size: c.size });
  });
}

// ── the noise-band sheet, drawn as a tolerance ─────────────────────────────────
const AX0 = 2.90, AX1 = 9.20, SPAN = 14;           // −7 % … +7 %
const U = (AX1 - AX0) / SPAN;
const ZERO = AX0 + 7 * U;
const xOf = (pct) => ZERO + pct * U;
const AY = 2.90;                                    // axis line
const ZTOP = 1.88;                                  // hatched zone, top
const COL = { x: PAD, w: 1.94, divider: 2.56 };     // the notes column

/** First line of a deck's band caption is its heading; the rest is its body. */
const headOf = (t) => (t || "").split("\n")[0];
const restOf = (t) => (t || "").split("\n").slice(1).join(" ").replace(/\s+/g, " ").trim();

/**
 * Typical error, drawn as a manufacturing tolerance.
 *
 * The band is not shaded with its explanation typeset inside it. It is a hatched zone
 * dimensioned in gold from a measured datum, with the explanation displaced to a notes
 * column — which is where a drawing puts prose. The threshold is a separate, dashed,
 * adjustable line, because it is chosen rather than measured, and that is the sheet's
 * whole argument.
 */
function toleranceDrawing(s, o) {
  const te = o.typicalError || 3.0;
  const XA = xOf(-te), XB = xOf(te);

  vrule(s, COL.divider, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, C.MID_GREEN);

  label(s, headOf(o.inside) || "Inside the noise floor",
    { x: COL.x, y: 1.10, w: COL.w, color: C.MINT_SOFT, size: 10, face: F.COND_MED });
  body(s, restOf(o.inside), { x: COL.x, y: 1.32, w: COL.w, h: 0.50, size: 11 });

  hrule(s, COL.x, 1.86, COL.w, C.MID_GREEN);
  label(s, "The dashed line", { x: COL.x, y: 1.96, w: COL.w, color: C.MINT_SOFT, size: 10, face: F.COND_MED });
  body(s, "Set by which error costs more. Not by the data.",
    { x: COL.x, y: 2.18, w: COL.w, h: 0.44, size: 11 });

  if (o.source) {
    hrule(s, COL.x, 2.72, COL.w, C.MID_GREEN);
    label(s, "Source", { x: COL.x, y: 2.82, w: COL.w, color: C.MINT, size: 8 });
    body(s, o.source, { x: COL.x, y: 2.99, w: COL.w, h: 0.42, size: 9 });
  }

  hatch(s, { x: XA, y: ZTOP, w: XB - XA, h: AY - ZTOP, color: C.MINT });
  hrule(s, XA, ZTOP, XB - XA, C.MINT_SOFT);
