  vrule(s, XB, 1.68, 2.98 - 1.68, C.MINT_SOFT);

  // The dimension, split at the centreline so a full-span arrow can never be read as
  // one double-width quantity. The one gold element on the sheet.
  s.addText("TYPICAL ERROR", {
    x: ZERO - 1.60, y: 1.00, w: 3.20, h: 0.28, fontSize: 15, fontFace: F.COND,
    bold: true, color: C.GOLD, align: "center", charSpacing: 1.6, valign: "top", margin: 0,
  });
  if (o.errorNote) {
    label(s, o.errorNote, { x: ZERO - 2.00, y: 1.29, w: 4.00, color: C.MINT, size: 8.5, align: "center" });
  }
  [[XA, ZERO, "left"], [ZERO, XB, "right"]].forEach(([x0, x1, outward]) => {
    hrule(s, x0 + 0.06, 1.76, x1 - x0 - 0.06, C.GOLD);
    arrow(s, { x: outward === "left" ? x0 + 0.07 : x1 - 0.07, y: 1.766, dir: outward, color: C.GOLD });
    s.addText(`${te.toFixed(1)} %`, {
      x: (x0 + x1) / 2 - 0.45, y: 1.46, w: 0.90, h: 0.24, fontSize: 11, fontFace: F.COND_MED,
      color: C.GOLD, align: "center", valign: "top", margin: 0,
    });
  });
  vrule(s, ZERO, 1.70, 0.14, C.GOLD);
  centreline(s, { x: ZERO, y0: 1.92, y1: 2.94, color: C.WHITE });

  // The threshold: dashed on both sides, because a person sets it and it is symmetric.
  const XT = o.thresholdAt || te * 1.5;
  [xOf(-XT), xOf(XT)].forEach((xt) => {
    for (let y = ZTOP + 0.04; y < AY - 0.02; y += 0.13) vrule(s, xt, y, 0.075, C.MINT_SOFT);
    hrule(s, xt - 0.24, 2.34, 0.48, C.MINT_SOFT);
    arrow(s, { x: xt - 0.24, y: 2.346, dir: "left", color: C.MINT_SOFT, size: 0.10 });
    arrow(s, { x: xt + 0.24, y: 2.346, dir: "right", color: C.MINT_SOFT, size: 0.10 });
  });
  label(s, "Threshold", { x: 8.38, y: 2.06, w: 1.24, color: C.MINT_SOFT, size: 10, face: F.COND_MED });
  body(s, "Position is arbitrary. Set by cost, not read off this axis.",
    { x: 8.38, y: 2.26, w: 1.24, h: 0.60, size: 9.5 });

  line(s, { x: 2.80, y: AY, w: 9.32 - 2.80, h: 0.014, color: C.MINT });
  for (let p = -7; p <= 7; p += 1) vrule(s, xOf(p), AY, p % 2 === 0 ? 0.09 : 0.05, C.MINT);
  label(s, "−7 %", { x: xOf(-7) - 0.35, y: 2.99, w: 0.70, h: 0.16, color: C.MINT, size: 9.5, align: "center" });
  label(s, "0", { x: ZERO - 0.25, y: 2.99, w: 0.50, h: 0.16, color: C.MINT, size: 9.5, align: "center" });
  label(s, "+7 %", { x: xOf(7) - 0.35, y: 2.99, w: 0.70, h: 0.16, color: C.MINT, size: 9.5, align: "center" });

  const readings = o.readings || [];
  const captions = { inside: restOf(o.inside), outside: restOf(o.outside) };
  const heads = { inside: headOf(o.inside), outside: headOf(o.outside) };
  const place = [
    { noteX: 2.80, noteW: 2.35 },
    { noteX: 5.45, noteW: 2.60 },
  ];
  readings.forEach((r, i) => {
    const inside = r.state === "inside";
    const tone = inside ? C.MINT_SOFT : C.WHITE;
    const p = place[i] || place[0];
    const x = xOf(r.pct);

    // A drawn line always wins against section hatch, so the hatch gives way.
    if (inside) line(s, { x: x - 0.05, y: 2.46, w: 0.10, h: AY - 2.46, color: C.GROUND_DARK });
    vrule(s, x, 2.46, AY - 2.46, tone, inside ? 0.018 : 0.020);
    s.addShape("rect", {
      x: x - 0.05, y: AY - 0.05, w: 0.10, h: 0.10,
      fill: { color: tone }, line: { color: tone, width: 0.25 },
    });
