    hrule(s, Math.min(x, p.noteX), 3.20, Math.abs(x - p.noteX) + HAIR, tone);
    vrule(s, p.noteX, 3.20, 0.06, tone);

    const sign = r.pct > 0 ? "+" : "−";
    label(s, `Reading ${r.id}   ${sign}${Math.abs(r.pct).toFixed(1)} %   · illustrative`,
      { x: p.noteX, y: 3.28, w: p.noteW, color: tone, size: 10, face: F.COND_MED });
    body(s, `${heads[r.state]}. ${captions[r.state]}`,
      { x: p.noteX, y: 3.48, w: p.noteW, h: 0.38, size: 10 });
