}

// ── a dimensioned comparison, for decks whose insight is a set of values ───────
function barsDrawing(s, { x, y, w, rows, max }) {
  if (rows.length > 4) {
    throw new Error(`bars got ${rows.length} rows; 4 is the maximum on a sheet this size`);
  }
  const accents = rows.filter((r) => r.accent).length;
  if (accents > 2) {
    throw new Error(`bars got ${accents} gold dimensions; 2 is the maximum — gold marks the point`);
  }
  const top = max || Math.max(...rows.map((r) => Math.abs(r.value)));
  const nameW = w * 0.30;
  const trackX = x + w * 0.33;
  const trackW = w * 0.40;
  const valueX = x + w * 0.76;

  let cy = y;
  rows.forEach((r) => {
    const len = Math.max(0.10, (Math.abs(r.value) / top) * trackW);
    const tone = r.accent ? C.GOLD : C.MINT;
    label(s, r.label, { x, y: cy, w: nameW, color: C.MINT_SOFT, size: 10, face: F.COND_MED });
    vrule(s, trackX, cy - 0.06, 0.34, C.MID_GREEN);            // extension lines
    vrule(s, trackX + len, cy - 0.06, 0.34, C.MID_GREEN);
    hrule(s, trackX + 0.06, cy + 0.11, len - 0.12, tone);
    arrow(s, { x: trackX + 0.07, y: cy + 0.116, dir: "left", color: tone, size: 0.10 });
    arrow(s, { x: trackX + len - 0.07, y: cy + 0.116, dir: "right", color: tone, size: 0.10 });
    s.addText(r.display, {
      x: valueX, y: cy - 0.02, w: w * 0.24, h: 0.26, fontSize: 11.5, fontFace: F.COND_MED,
      color: tone, valign: "top", margin: 0,
    });
    cy += 0.56;
  });
  return cy;
}

// ── two states, drawn as two parts, one of which is scrapped ───────────────────
function splitDrawing(s, { x, y, w, kept, lost }) {
  const half = (w - 0.44) / 2;
  const h = 1.44;
  [{ ...kept, cx: x, ok: true }, { ...lost, cx: x + half + 0.44, ok: false }].forEach((p) => {
    hrule(s, p.cx, y, half, p.ok ? C.MINT_SOFT : C.GOLD);
    hrule(s, p.cx, y + h, half, p.ok ? C.MINT_SOFT : C.GOLD);
    vrule(s, p.cx, y, h, p.ok ? C.MINT_SOFT : C.GOLD);
    vrule(s, p.cx + half, y, h, p.ok ? C.MINT_SOFT : C.GOLD);
    if (!p.ok) hatch(s, { x: p.cx, y, w: half, h, step: 0.30, color: C.MID_GREEN, width: 0.6 });
    label(s, p.tag, {
      x: p.cx + 0.16, y: y + 0.12, w: half - 0.32,
      color: p.ok ? C.MINT : C.GOLD, size: 8.5,
    });
    s.addText(p.head, {
      x: p.cx + 0.16, y: y + 0.34, w: half - 0.32, h: 0.40, fontSize: 16,
      fontFace: F.COND_MED, color: C.WHITE, valign: "top", margin: 0,
    });
    body(s, p.body, { x: p.cx + 0.16, y: y + 0.76, w: half - 0.32, h: h - 0.90, size: 10 });
  });
  return y + h;
}

function visualsFor(s, region) {
  return {
    bars: (o) => barsDrawing(s, { ...region, ...o }),
    band: (o) => toleranceDrawing(s, o),
    split: (o) => splitDrawing(s, { ...region, ...o }),
  };
}

// ── the set ────────────────────────────────────────────────────────────────────
async function buildDeck(d, outPath) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Baylor Athletics · Applied Performance";
  pres.title = `${d.title} — 5 Slides in 5 Minutes (shop drawing)`;

  // 1 — cover sheet. The one display line the house style allows, at plan scale.
  {
    const s = sheet(pres, d, {
      n: 1, title: d.title,
      caption: "Cover sheet — the question this drawing answers",
    });
    s.addText(`${d.hook.display}\n${d.hook.accent}`, {
      x: PAD, y: 1.12, w: 5.10, h: 1.90, fontSize: 42, fontFace: F.DISPLAY,
      color: C.WHITE, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.14,
    });
    vrule(s, 5.90, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, C.MID_GREEN);

    label(s, "Scope", { x: 6.10, y: 1.10, w: 3.44, color: C.MINT, size: 8 });
    body(s, d.coreQuestion, { x: 6.10, y: 1.28, w: 3.44, h: 0.70, size: 11, color: C.MINT_SOFT });
    hrule(s, 6.10, 2.10, 3.44, C.MID_GREEN);
    label(s, "For", { x: 6.10, y: 2.20, w: 3.44, color: C.MINT, size: 8 });
    body(s, d.hook.sub.replace(/\n/g, " "), { x: 6.10, y: 2.38, w: 3.44, h: 1.20, size: 10 });

    notes(s, [
      "Every number on these sheets traces to a source. Where the evidence is thin or contested, the sheet says so rather than rounding it off.",
      "Figures shown as examples are labelled illustrative.",
      "Applied Performance supplies evidence. It does not clear athletes to play.",
    ]);
    s.addNotes(d.hook.notes);
  }

  // 2 — the problem, with the measured quantity dimensioned rather than asserted.
  {
    const s = sheet(pres, d, {
      n: 2, title: d.problem.head,
      caption: "The problem — what the software cannot tell you",
    });
    s.addText(d.problem.stat, {
      x: PAD, y: 1.16, w: 3.00, h: 0.94, fontSize: 54, fontFace: F.COND, bold: true,
      color: C.GOLD, align: "left", valign: "top", margin: 0,
    });
    hrule(s, PAD + 0.06, 2.14, 2.28, C.GOLD);
    arrow(s, { x: PAD + 0.07, y: 2.146, dir: "left", color: C.GOLD, size: 0.10 });
    arrow(s, { x: PAD + 2.34 - 0.07, y: 2.146, dir: "right", color: C.GOLD, size: 0.10 });
    label(s, "Measured, not assumed", { x: PAD, y: 2.24, w: 3.00, color: C.MINT, size: 8.5 });
    body(s, d.problem.statCaption, { x: PAD, y: 2.46, w: 3.00, h: 1.10, size: 10 });

    vrule(s, 3.72, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, C.MID_GREEN);
    label(s, "What the software reports", { x: 3.92, y: 1.10, w: 5.62, color: C.MINT_SOFT, size: 10, face: F.COND_MED });
    body(s, d.problem.body, { x: 3.92, y: 1.32, w: 5.62, h: 2.10, size: 11 });

    notes(s, [
      "An ICC of 0.96 is about as reliable as applied testing gets, and the test still carries 3 % of measurement noise.",
      "Group-derived thresholds lack the resolution to guide one athlete's day-to-day decisions.",
      "Rebelo et al., Sports Medicine 2026.",
    ]);
    s.addNotes(d.problem.notes);
  }

  // 3 — the insight. The deck names the visual; this direction draws it as a tolerance.
  {
    const s = sheet(pres, d, {
      n: 3, title: d.insight.head,
      caption: "The noise floor — before a number is allowed to mean something",
    });
    d.insight.visual(visualsFor(s, { x: 2.80, y: 1.10, w: 6.74 }));
    notes(s, [
      d.insight.foot,
      "Readings and the threshold position shown are illustrative.",
      "Rebelo et al., Sports Medicine 2026.",
    ]);
    s.addNotes(d.insight.notes);
  }

  // 4 — the schedule. A bill of materials is the drawing's own way of saying who does
  //     what, and it enforces the ordering the slide is actually about.
  {
    const s = sheet(pres, d, {
      n: 4, title: d.apply.head,
      caption: "On Monday — the schedule",
    });
    label(s, "Item", { x: PAD, y: 1.04, w: 0.60, color: C.MINT, size: 8 });
    label(s, "Role", { x: 1.16, y: 1.04, w: 2.10, color: C.MINT, size: 8 });
    label(s, "What changes on Monday", { x: 3.40, y: 1.04, w: 6.14, color: C.MINT, size: 8 });
    hrule(s, PAD, 1.24, 9.54 - PAD, C.MINT_SOFT);

    let ry = 1.34;
    d.apply.columns.forEach((c, i) => {
      s.addText(String(i + 1).padStart(2, "0"), {
        x: PAD, y: ry, w: 0.60, h: 0.24, fontSize: 12, fontFace: F.COND,
        color: C.GOLD_INK === C.GOLD ? C.GOLD : C.MINT, valign: "top", margin: 0,
      });
      s.addText(c.who, {
        x: 1.16, y: ry, w: 2.10, h: 0.50, fontSize: 10.5, fontFace: F.COND_MED,
        color: C.MINT_SOFT, valign: "top", margin: 0, lineSpacingMultiple: 1.06,
      });
      body(s, c.what, { x: 3.40, y: ry, w: 6.14, h: 0.50, size: 9.5 });
      ry += 0.60;
      hrule(s, PAD, ry - 0.09, 9.54 - PAD, C.MID_GREEN);
    });

    notes(s, [
      d.apply.rule,
      "The order is the point. The instinct is to start at the last question.",
      "For most of our own tests the typical error is not established yet. That is the first task.",
    ]);
    s.addNotes(d.apply.notes);
  }

  // 5 — the one thing, set in a ruled panel, with the question left open under it.
  {
    const s = sheet(pres, d, {
      n: 5, title: "The one thing",
      caption: "The one thing — and the question to leave in the room",
    });
    hrule(s, PAD, 1.16, 9.54 - PAD, C.MINT_SOFT);
    hrule(s, PAD, 2.36, 9.54 - PAD, C.MINT_SOFT);
    s.addText(d.takeaway.oneThing, {
      x: PAD, y: 1.34, w: 8.90, h: 0.90, fontSize: 20, fontFace: F.COND_MED,
      color: C.WHITE, valign: "top", margin: 0, lineSpacingMultiple: 1.08,
    });

    label(s, "For the room", { x: PAD, y: 2.52, w: 5.60, color: C.GOLD, size: 9 });
    body(s, d.takeaway.question,
      { x: PAD, y: 2.74, w: 5.60, h: 0.80, size: 12, color: C.MINT_SOFT, italic: true });

    notes(s, [
      "Where missing early maladaptation is the costlier mistake, the source supports a more sensitive threshold on purpose. This is not an argument for acting on less.",
      "Applied Performance supplies evidence. Return-to-play clearance is a medical decision.",
      "Rebelo et al., Sports Medicine 2026.",
    ]);
    s.addNotes(d.takeaway.notes);
  }

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

module.exports = { buildDeck, name: "shop-drawing" };

