/**
 * THESIS: a five-minute argument is a set of drawings, not a set of headlines. Every
 *   sheet dimensions its evidence the way a shop drawing dimensions a part, so the room
 *   reads a measurement before it reads a claim. Refuses the category default — a title
 *   over a picture over a caption — on all five sheets, not just the one with a chart.
 * OWN-WORLD: a drawing set issued two ways. Odd sheets are blueprint (forest ground,
 *   mint linework, Baylor gold). Even sheets are whiteprint (bone ground, green
 *   linework, antique gold). Both carry the same frame, the same 45° section hatch, the
 *   same condensed all-caps annotation, the same four vertical stations, the same ruled
 *   notes row and three-cell title block. Recognisable with every word removed.
 * STORY: the room opens a drawing set — the question and the running time on the cover,
 *   the measured problem on sheet 2, the same band at full scale on sheet 3, the order
 *   of operations and the schedule on sheet 4, one line to carry out on sheet 5.
 * FIRST VIEWPORT: sheet 1 is a cover — display line at plan scale on the left over a
 *   dimensioned five-minute strip, scope / issued-to / source ruled into cells on the
 *   right, the drawing's name in the title block.
 * FORM: the tolerance drawing, extended from one sheet to the set. Seed key 24b50457.
 * FINISH: unreviewed and undocumented is unfinished; this build ends with the finish
 *   review, the verdict, and DESIGN.md
 *
 * A direction is a kit, not a rewrite of five decks. Content files declare what kind of
 * visual they need — bars, a noise band, a two-state split — and this file decides how
 * that gets drawn. Nothing here reaches into a deck's narrative.
 *
 * Second pass, after the set review. The first build put a frame and a title block
 * around three sheets of prose and called it a drawing set; the reviewer was right that
 * the thesis was carried on one and a half sheets. Every sheet now has a drawn,
 * dimensioned object: a five-minute strip on the cover, the band at small scale on the
 * problem sheet so sheet 3 arrives as a zoom, the three questions as an ordered
 * dimension on the schedule sheet, and a bracketed panel on the takeaway. The body
 * dividers moved onto four declared stations, because a drawing set's vertical stations
 * are what make it a set.
 */
const pptxgen = require("pptxgenjs");
const { C, F } = require("../_kit");

// ── the sheet ──────────────────────────────────────────────────────────────────
const HAIR = 0.012;                 // interior hairline
const RULE_W = 0.015;               // header, notes and title-block rules
const FRAME_W = 0.018;              // the outer frame, which the whole world rests on
const B = { x0: 0.30, y0: 0.26, x1: 9.70, y1: 5.36 };
const PAD = 0.46;
const GUT = 0.16;                   // one gutter, everywhere
const RIGHT = 9.54;                 // where content stops, one gutter off the frame
const HEAD_RULE = 0.82;
const DRAW_TOP = 0.94;
const DRAW_BOT = 3.86;
const NOTE_RULE = 3.92;
const TB = 4.60;                    // title block

/**
 * Four vertical stations. A body division may land on one of these and nowhere else —
 * the first build picked a different arbitrary x on every sheet, which is what made the
 * set read as five layouts sharing a footer.
 */
const ST = { A: 2.56, B: 3.40, C: 5.55, D: 7.70 };

const TONE = {
  dark: {
    ground: C.GROUND_DARK,
    rule: C.MID_GREEN,        // interior hairlines
    frame: C.MINT,            // the outer frame and the major rules
    edge: C.MINT_SOFT,        // the heavier boundary of a drawn region
    label: C.MINT,
    head: C.MINT_SOFT,
    body: C.MINT,
    display: C.WHITE,
    accent: C.GOLD,           // dark grounds only
    hatch: C.MINT,
  },
  light: {
    ground: C.GROUND_LIGHT,
    rule: C.BONE_LINE,
    frame: C.GRAY_INK,
    edge: C.GREEN,
    label: C.GRAY_INK,
    head: C.GREEN,
    body: C.GRAY_INK,
    display: C.GREEN,
    accent: C.GOLD_INK,       // Baylor gold is 1.7:1 on bone and never appears there
    hatch: C.GREEN,
  },
};

// Every straight line on these sheets is a filled rect. pptxgenjs 4 writes a 1pt
// #333333 outline onto any shape that asks for no border, so nothing here asks for one.
function line(s, { x, y, w, h, color }) {
  s.addShape("rect", { x, y, w, h, fill: { color }, line: { color, width: 0.25 } });
}
const hrule = (s, x, y, w, color, t = HAIR) => line(s, { x, y, w, h: t, color });
const vrule = (s, x, y, h, color, t = HAIR) => line(s, { x, y, w: t, h, color });

/** A drafting arrowhead. `dir` is the direction it points. */
function arrow(s, { x, y, dir, color, size = 0.12 }) {
  s.addShape("triangle", {
    x: x - size / 2, y: y - size / 2, w: size, h: size,
    fill: { color }, line: { color, width: 0.25 },
    rotate: dir === "left" ? 270 : 90,
  });
}

/** A dimension: extension lines, a double-arrowed rule, and the value above it. */
function dimension(s, { x0, x1, y, color, text, size = 10, ext, extTop }) {
  if (ext) {
    vrule(s, x0, extTop, ext, color);
    vrule(s, x1, extTop, ext, color);
  }
  hrule(s, x0 + 0.06, y, x1 - x0 - 0.12, color);
  arrow(s, { x: x0 + 0.07, y: y + 0.006, dir: "left", color, size: 0.10 });
  arrow(s, { x: x1 - 0.07, y: y + 0.006, dir: "right", color, size: 0.10 });
  if (text) {
    s.addText(text.toUpperCase(), {
      x: (x0 + x1) / 2 - 1.2, y: y - 0.28, w: 2.4, h: 0.24, fontSize: size,
      fontFace: F.COND_MED, color, align: "center", charSpacing: 1.2,
      valign: "top", margin: 0,
    });
  }
}

/** 45° section hatch, clipped to the rect. Drafting says "this region is excluded". */
function hatch(s, { x, y, w, h, step = 0.18, color, width = 0.5 }) {
  for (let k = -h; k < w; k += step) {
    const t0 = Math.max(-k, 0);
    const t1 = Math.min(w - k, h);
    if (t1 - t0 < 0.02) continue;
    s.addShape("line", {
      x: x + k + t0, y: y + t0, w: t1 - t0, h: t1 - t0,
      line: { color, width },
    });
  }
}

/**
 * A drafting centreline: long dash, short dash, repeat.
 *
 * Heavier and brighter than any adjustable line on the sheet, on purpose. A datum is
 * measured and a threshold is chosen, and that distinction cannot rest on dash rhythm,
 * which does not survive a projector.
 */
function centreline(s, { x, y0, y1, color }) {
  let y = y0;
  let long = true;
  while (y < y1) {
    const seg = Math.min(long ? 0.17 : 0.05, y1 - y);
    vrule(s, x, y, seg, color, 0.020);
    y += seg + 0.055;
    long = !long;
  }
}

function label(s, text, { x, y, w, color, size = 8, align = "left", face = F.COND, h = 0.20 }) {
  s.addText(text.toUpperCase(), {
    x, y, w, h, fontSize: size, fontFace: face, color, align,
    charSpacing: 1.1, valign: "top", margin: 0,
  });
}

function body(s, text, { x, y, w, h, color, size = 10.5 }) {
  s.addText(text, {
    x, y, w, h, fontSize: size, fontFace: F.BODY_LIGHT, color,
    valign: "top", margin: 0, lineSpacingMultiple: 1.12,
  });
}

/** Split prose into sentences, then group it into n cells. */
function deal(text, counts) {
  const parts = (text || "").match(/[^.]+\./g) || [text];
  const out = [];
  let i = 0;
  counts.forEach((n) => {
    out.push(parts.slice(i, i + n).join(" ").trim());
    i += n;
  });
  if (i < parts.length) out[out.length - 1] += ` ${parts.slice(i).join(" ").trim()}`;
  return out;
}

/**
 * The chrome every sheet in the set shares: frame, header rule, notes rule, title
 * block. Drawn first so a sheet's own content sits on top of it, and identical on all
 * five so the set reads as one drawing rather than five slides.
 */
function sheet(pres, d, { n, caption, title, dark }) {
  const T = dark ? TONE.dark : TONE.light;
  const s = pres.addSlide();
  s.background = { color: T.ground };

  hrule(s, B.x0, B.y0, B.x1 - B.x0, T.frame, FRAME_W);
  hrule(s, B.x0, B.y1, B.x1 - B.x0, T.frame, FRAME_W);
  vrule(s, B.x0, B.y0, B.y1 - B.y0, T.frame, FRAME_W);
  vrule(s, B.x1, B.y0, B.y1 - B.y0, T.frame, FRAME_W);
  hrule(s, B.x0, HEAD_RULE, B.x1 - B.x0, T.frame, RULE_W);

  label(s, caption, { x: PAD, y: 0.46, w: 5.2, color: T.label, size: 9 });
  label(s, `${d.topic} · 5 Slides in 5 Minutes`,
    { x: 6.10, y: 0.46, w: RIGHT - 6.10, color: T.label, size: 9, align: "right" });

  // The foot is one structure: the notes rule and the title block share two stations.
  hrule(s, B.x0, NOTE_RULE, B.x1 - B.x0, T.frame, RULE_W);
  vrule(s, ST.C, NOTE_RULE, B.y1 - NOTE_RULE, T.rule);
  vrule(s, ST.D, NOTE_RULE, B.y1 - NOTE_RULE, T.rule);
  hrule(s, B.x0, TB, B.x1 - B.x0, T.frame, RULE_W);

  label(s, "Title", { x: PAD, y: TB + 0.05, w: 2.0, color: T.label, size: 7.5 });
  s.addText(title, {
    x: PAD, y: TB + 0.19, w: 5.02, h: 0.54, fontSize: 21, fontFace: F.COND_MED,
    color: T.display, valign: "top", margin: 0, lineSpacingMultiple: 1.02,
  });

  label(s, "Subject", { x: 5.71, y: TB + 0.05, w: 1.9, color: T.label, size: 7.5 });
  s.addText(d.topic, {
    x: 5.71, y: TB + 0.19, w: 1.9, h: 0.22, fontSize: 10, fontFace: F.COND_MED,
    color: T.head, valign: "top", margin: 0,
  });
  s.addText("Baylor Athletics · Applied Performance", {
    x: 5.71, y: TB + 0.42, w: 1.9, h: 0.20, fontSize: 7.5, fontFace: F.BODY_LIGHT,
    color: T.body, valign: "top", margin: 0,
  });

  label(s, "Sheet", { x: 7.86, y: TB + 0.05, w: 1.7, color: T.label, size: 7.5 });
  s.addText(`${n} / 5`, {
    x: 7.86, y: TB + 0.19, w: 1.7, h: 0.26, fontSize: 13, fontFace: F.COND,
    color: T.head, valign: "top", margin: 0, charSpacing: 1,
  });

  return { s, T };
}

/** The three general-note cells, on the sheet's own stations. */
function notes(s, T, cells) {
  const cols = [
    { x: PAD, w: 4.93, size: 9 },
    { x: 5.71, w: 1.83, size: 8.5 },
    { x: 7.86, w: 1.68, size: 8 },
  ];
  cells.forEach((text, i) => {
    if (!text) return;
    const c = cols[i];
    label(s, `Note ${i + 1}`, { x: c.x, y: NOTE_RULE + 0.04, w: 1.2, h: 0.12, color: T.head, size: 8 });
    body(s, text, { x: c.x, y: NOTE_RULE + 0.17, w: c.w, h: 0.44, size: c.size, color: T.body });
  });
}

// ── the band, drawn as a tolerance ─────────────────────────────────────────────
const SPAN = 14;                                    // −7 % … +7 %

/** Geometry for a band drawn between x0 and x1. Used at full scale and at preview scale. */
function scaleOf(x0, x1) {
  const u = (x1 - x0) / SPAN;
  const zero = x0 + 7 * u;
  return { u, zero, at: (pct) => zero + pct * u };
}

const AX0 = 2.90, AX1 = 9.20;
const S = scaleOf(AX0, AX1);
const AY = 2.90;                                    // axis line
const ZTOP = 1.88;                                  // hatched zone, top
const COL = { x: PAD, w: 1.94, divider: ST.A };     // the notes column

const restOf = (t) => (t || "").split("\n").slice(1).join(" ").replace(/\s+/g, " ").trim();

/**
 * Typical error, drawn as a manufacturing tolerance.
 *
 * The band is not shaded with its explanation typeset inside it. It is a hatched zone
 * dimensioned from a measured datum, with the explanation displaced to a notes column —
 * which is where a drawing puts prose. The threshold is a separate, dashed, adjustable
 * line, because it is chosen rather than measured, and that is the sheet's whole
 * argument.
 */
function toleranceDrawing(s, T, o) {
  const te = o.typicalError || 3.0;
  const XA = S.at(-te), XB = S.at(te);

  vrule(s, COL.divider, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, T.rule);

  label(s, "Inside the noise floor",
    { x: COL.x, y: 1.10, w: COL.w, color: T.head, size: 10, face: F.COND_MED });
  body(s, restOf(o.inside), { x: COL.x, y: 1.32, w: COL.w, h: 0.84, size: 10.5, color: T.body });

  hrule(s, COL.x, 2.20, COL.w, T.rule);
  label(s, "The dashed line", { x: COL.x, y: 2.30, w: COL.w, color: T.head, size: 10, face: F.COND_MED });
  body(s, "Set by which error costs more. Not by the data.",
    { x: COL.x, y: 2.52, w: COL.w, h: 0.44, size: 10.5, color: T.body });

  if (o.source) {
    hrule(s, COL.x, 3.04, COL.w, T.rule);
    label(s, "Source", { x: COL.x, y: 3.14, w: COL.w, color: T.label, size: 8 });
    body(s, o.source, { x: COL.x, y: 3.30, w: COL.w, h: 0.42, size: 9, color: T.body });
  }

  hatch(s, { x: XA, y: ZTOP, w: XB - XA, h: AY - ZTOP, color: T.hatch });
  hrule(s, XA, ZTOP, XB - XA, T.edge);
  vrule(s, XA, 1.68, 2.98 - 1.68, T.edge);
  vrule(s, XB, 1.68, 2.98 - 1.68, T.edge);

  // Split at the centreline, so a full-span arrow can never be read as one
  // double-width quantity. The one accent on the sheet.
  s.addText("TYPICAL ERROR", {
    x: S.zero - 1.60, y: 1.00, w: 3.20, h: 0.28, fontSize: 15, fontFace: F.COND,
    bold: true, color: T.accent, align: "center", charSpacing: 1.6, valign: "top", margin: 0,
  });
  if (o.errorNote) {
    label(s, o.errorNote, { x: S.zero - 2.20, y: 1.29, w: 4.40, color: T.body, size: 8.5, align: "center" });
  }
  [[XA, S.zero, "left"], [S.zero, XB, "right"]].forEach(([x0, x1, outward]) => {
    hrule(s, x0 + 0.06, 1.76, x1 - x0 - 0.06, T.accent);
    arrow(s, { x: outward === "left" ? x0 + 0.07 : x1 - 0.07, y: 1.766, dir: outward, color: T.accent });
    s.addText(`${te.toFixed(1)} %`, {
      x: (x0 + x1) / 2 - 0.45, y: 1.46, w: 0.90, h: 0.24, fontSize: 11, fontFace: F.COND_MED,
      color: T.accent, align: "center", valign: "top", margin: 0,
    });
  });
  vrule(s, S.zero, 1.70, 0.14, T.accent);
  centreline(s, { x: S.zero, y0: 1.92, y1: 2.94, color: T.display });

  // The threshold: dashed on both sides, because a person sets it and it is symmetric.
  const XT = o.thresholdAt || te * 1.5;
  [S.at(-XT), S.at(XT)].forEach((xt) => {
    for (let y = ZTOP + 0.04; y < AY - 0.02; y += 0.13) vrule(s, xt, y, 0.075, T.edge);
    hrule(s, xt - 0.24, 2.34, 0.48, T.edge);
    arrow(s, { x: xt - 0.24, y: 2.346, dir: "left", color: T.edge, size: 0.10 });
    arrow(s, { x: xt + 0.24, y: 2.346, dir: "right", color: T.edge, size: 0.10 });
  });
  label(s, "Threshold", { x: 8.30, y: 2.02, w: RIGHT - 8.30, color: T.head, size: 10, face: F.COND_MED });
  body(s, "Position is arbitrary. Set by cost, not by this axis.",
    { x: 8.30, y: 2.22, w: RIGHT - 8.30, h: 0.56, size: 9, color: T.body });

  line(s, { x: 2.80, y: AY, w: 9.32 - 2.80, h: 0.014, color: T.body });
  for (let p = -7; p <= 7; p += 1) vrule(s, S.at(p), AY, p % 2 === 0 ? 0.09 : 0.05, T.body);
  label(s, "−7 %", { x: S.at(-7) - 0.35, y: 2.96, w: 0.70, h: 0.15, color: T.body, size: 9, align: "center" });
  label(s, "0", { x: S.zero - 0.25, y: 2.96, w: 0.50, h: 0.15, color: T.body, size: 9, align: "center" });
  label(s, "+7 %", { x: S.at(7) - 0.35, y: 2.96, w: 0.70, h: 0.15, color: T.body, size: 9, align: "center" });

  const captions = { outside: restOf(o.outside) };
  const place = [{ noteX: 2.80, noteW: 2.35 }, { noteX: 5.45, noteW: 2.60 }];

  (o.readings || []).forEach((r, i) => {
    const inside = r.state === "inside";
    const tone = inside ? T.head : T.display;
    const p = place[i] || place[0];
    const x = S.at(r.pct);

    // A drawn line always wins against section hatch, so the hatch gives way.
    if (inside) line(s, { x: x - 0.05, y: 2.46, w: 0.10, h: AY - 2.46, color: T.ground });
    vrule(s, x, 2.46, AY - 2.46, tone, inside ? 0.018 : 0.020);
    s.addShape("rect", {
      x: x - 0.05, y: AY - 0.05, w: 0.10, h: 0.10,
      fill: { color: tone }, line: { color: tone, width: 0.25 },
    });
    vrule(s, x, AY + 0.04, 3.12 - AY - 0.04, tone);
    hrule(s, Math.min(x, p.noteX), 3.12, Math.abs(x - p.noteX) + HAIR, tone);
    vrule(s, p.noteX, 3.12, 0.06, tone);

    const sign = r.pct > 0 ? "+" : "−";
    label(s, `Reading ${r.id}   ${sign}${Math.abs(r.pct).toFixed(1)} %   · illustrative`,
      { x: p.noteX, y: 3.20, w: p.noteW, color: tone, size: 10, face: F.COND_MED });
    body(s, inside ? "Inside the noise floor. The test cannot tell this from noise."
      : `Clears the noise floor. ${captions.outside}`,
    { x: p.noteX, y: 3.39, w: p.noteW, h: 0.46, size: 9.5, color: T.body });
  });

  return DRAW_BOT;
}

/**
 * The same band at preview scale, for the sheet that introduces the quantity.
 *
 * Drawing it small on sheet 2 and full size on sheet 3 makes the insight sheet arrive as
 * a zoom rather than a new idea, and it gives the problem sheet a dimension that
 * measures something instead of a rule that measures nothing.
 */
function bandPreview(s, T, { x0, x1, y, te = 3.0 }) {
  const m = scaleOf(x0, x1);
  const XA = m.at(-te), XB = m.at(te);
  const zoneTop = y + 0.10, axis = y + 0.50;

  hatch(s, { x: XA, y: zoneTop, w: XB - XA, h: axis - zoneTop, color: T.hatch, step: 0.11, width: 0.4 });
  hrule(s, XA, zoneTop, XB - XA, T.edge);
  dimension(s, {
    x0: XA, x1: XB, y: y - 0.06, color: T.accent, text: `± ${te.toFixed(1)} %`, size: 9.5,
    ext: axis - (y - 0.14) + 0.08, extTop: y - 0.14,
  });
  line(s, { x: x0 - 0.10, y: axis, w: x1 - x0 + 0.20, h: 0.012, color: T.body });
  for (let p = -7; p <= 7; p += 1) vrule(s, m.at(p), axis, p % 2 === 0 ? 0.06 : 0.035, T.body);
  label(s, "0", { x: m.zero - 0.25, y: axis + 0.08, w: 0.50, h: 0.14, color: T.body, size: 7.5, align: "center" });
  label(s, "Drawn full size on sheet 3", { x: x0, y: axis + 0.24, w: x1 - x0, color: T.label, size: 7.5 });
  return axis + 0.42;
}

// ── a dimensioned comparison, for decks whose insight is a set of values ───────
function barsDrawing(s, T, { x, y, w, rows, max }) {
  if (rows.length > 4) {
    throw new Error(`bars got ${rows.length} rows; 4 is the maximum on a sheet this size`);
  }
  const accents = rows.filter((r) => r.accent).length;
  if (accents > 2) {
    throw new Error(`bars got ${accents} accented dimensions; 2 is the maximum — the accent marks the point`);
  }
  const top = max || Math.max(...rows.map((r) => Math.abs(r.value)));
  const trackX = x + w * 0.33;
  const trackW = w * 0.40;
  const valueX = x + w * 0.76;

  let cy = y;
  rows.forEach((r) => {
    const len = Math.max(0.14, (Math.abs(r.value) / top) * trackW);
    const tone = r.accent ? T.accent : T.body;
    label(s, r.label, { x, y: cy, w: w * 0.30, color: T.head, size: 10, face: F.COND_MED });
    dimension(s, {
      x0: trackX, x1: trackX + len, y: cy + 0.11, color: tone,
      ext: 0.34, extTop: cy - 0.06,
    });
    s.addText(r.display, {
      x: valueX, y: cy - 0.02, w: w * 0.24, h: 0.26, fontSize: 11.5, fontFace: F.COND_MED,
      color: tone, valign: "top", margin: 0,
    });
    cy += 0.56;
  });
  return cy;
}

// ── two states, drawn as two parts, one of which is scrapped ───────────────────
function splitDrawing(s, T, { x, y, w, kept, lost }) {
  const half = (w - 0.44) / 2;
  const h = 1.44;
  [{ ...kept, cx: x, ok: true }, { ...lost, cx: x + half + 0.44, ok: false }].forEach((p) => {
    const edge = p.ok ? T.edge : T.accent;
    hrule(s, p.cx, y, half, edge);
    hrule(s, p.cx, y + h, half, edge);
    vrule(s, p.cx, y, h, edge);
    vrule(s, p.cx + half, y, h, edge);
    if (!p.ok) hatch(s, { x: p.cx, y, w: half, h, step: 0.30, color: T.rule, width: 0.6 });
    label(s, p.tag, { x: p.cx + 0.16, y: y + 0.12, w: half - 0.32, color: edge, size: 8.5 });
    s.addText(p.head, {
      x: p.cx + 0.16, y: y + 0.34, w: half - 0.32, h: 0.40, fontSize: 16,
      fontFace: F.COND_MED, color: T.display, valign: "top", margin: 0,
    });
    body(s, p.body, { x: p.cx + 0.16, y: y + 0.76, w: half - 0.32, h: h - 0.90, size: 10, color: T.body });
  });
  return y + h;
}

function visualsFor(s, T, region) {
  return {
    bars: (o) => barsDrawing(s, T, { ...region, ...o }),
    band: (o) => toleranceDrawing(s, T, o),
    split: (o) => splitDrawing(s, T, { ...region, ...o }),
  };
}

// ── the set ────────────────────────────────────────────────────────────────────
const SHEET_NAMES = ["Cover", "The problem", "The noise floor", "The schedule", "The one thing"];

async function buildDeck(d, outPath) {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Baylor Athletics · Applied Performance";
  pres.title = `${d.title} — 5 Slides in 5 Minutes (shop drawing)`;

  // 1 — cover sheet. The display line the house style allows once, over a strip that
  //     dimensions the running time and names every sheet in the set.
  {
    const { s, T } = sheet(pres, d, {
      n: 1, dark: true, title: d.title,
      caption: "Cover sheet — the question this drawing answers",
    });
    s.addText(`${d.hook.display}\n${d.hook.accent}`, {
      x: PAD, y: 1.06, w: 5.0, h: 1.30, fontSize: 38, fontFace: F.DISPLAY,
      color: T.display, align: "left", valign: "top", margin: 0, lineSpacingMultiple: 1.12,
    });
    body(s, d.hook.sub.replace(/\n/g, " "),
      { x: PAD, y: 2.42, w: 5.0, h: 0.50, size: 11, color: T.body });

    // The five minutes, dimensioned. Five ticks, one per sheet, and a marker on this one.
    const sx0 = PAD, sx1 = 5.46, sy = 3.46;
    dimension(s, {
      x0: sx0, x1: sx1, y: 3.16, color: T.accent, text: "5 minutes", size: 10,
      ext: 0.42, extTop: 3.08,
    });
    line(s, { x: sx0, y: sy, w: sx1 - sx0, h: 0.012, color: T.body });
    SHEET_NAMES.forEach((nm, i) => {
      const tx = sx0 + ((sx1 - sx0) / 5) * (i + 0.5);
      vrule(s, tx, sy, 0.07, T.body);
      label(s, nm, { x: tx - 0.50, y: sy + 0.10, w: 1.00, h: 0.14, color: T.label, size: 7, align: "center" });
      if (i === 0) {
        s.addShape("rect", {
          x: tx - 0.045, y: sy - 0.045, w: 0.09, h: 0.09,
          fill: { color: T.display }, line: { color: T.display, width: 0.25 },
        });
      }
    });

    vrule(s, ST.C, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, T.rule);
    const rx = ST.C + GUT, rw = RIGHT - ST.C - GUT;
    label(s, "Scope", { x: rx, y: 1.10, w: rw, color: T.label, size: 8 });
    body(s, d.coreQuestion, { x: rx, y: 1.28, w: rw, h: 0.62, size: 11, color: T.head });

    hrule(s, rx, 2.00, rw, T.rule);
    label(s, "Issued to", { x: rx, y: 2.10, w: rw, color: T.label, size: 8 });
    body(s, "Baylor Health & Wellness staff — strength & conditioning, athletic medicine, sport science, nutrition, mental health.",
      { x: rx, y: 2.28, w: rw, h: 0.80, size: 10, color: T.body });

    hrule(s, rx, 3.14, rw, T.rule);
    label(s, "Source", { x: rx, y: 3.24, w: rw, color: T.label, size: 8 });
    body(s, "Rebelo et al., Sports Medicine 2026.",
      { x: rx, y: 3.42, w: rw, h: 0.32, size: 9, color: T.body });

    notes(s, T, [
      "Applied Performance supplies evidence. It does not clear athletes to play.",
      "Figures shown as examples are labelled illustrative.",
      "",
    ]);
    s.addNotes(d.hook.notes);
  }

  // 2 — the problem. The measured quantity is dimensioned, and the band it defines is
  //     drawn small here so sheet 3 reads as a zoom rather than a new idea.
  {
    const { s, T } = sheet(pres, d, {
      n: 2, dark: false, title: d.problem.head,
      caption: "The problem — what the software cannot tell you",
    });
    s.addText(d.problem.stat, {
      x: PAD, y: 1.04, w: 2.80, h: 0.84, fontSize: 48, fontFace: F.COND, bold: true,
      color: T.accent, align: "left", valign: "top", margin: 0,
    });
    label(s, "Coefficient of variation · ICC 0.96",
      { x: PAD, y: 1.88, w: 2.80, color: T.label, size: 8.5 });
    bandPreview(s, T, { x0: 0.62, x1: 3.08, y: 2.36 });
    body(s, d.problem.statCaption, { x: PAD, y: 3.24, w: 2.80, h: 0.58, size: 9.5, color: T.body });

    vrule(s, ST.B, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, T.rule);
    const mx = ST.B + GUT, mw = ST.D - ST.B - GUT * 2;
    label(s, "What the software reports",
      { x: mx, y: 1.10, w: mw, color: T.head, size: 10, face: F.COND_MED });
    body(s, d.problem.body, { x: mx, y: 1.34, w: mw, h: 2.30, size: 11, color: T.body });

    vrule(s, ST.D, DRAW_TOP, DRAW_BOT - DRAW_TOP - 0.16, T.rule);
    label(s, "Read as", { x: 7.86, y: 1.10, w: 1.68, color: T.label, size: 8 });
    body(s, "The value is reported. The error of the test that produced it is not.",
      { x: 7.86, y: 1.28, w: 1.68, h: 0.80, size: 9.5, color: T.body });

    notes(s, T, [
      "An ICC of 0.96 is about as reliable as applied testing gets, and the test still carries 3 % of measurement noise.",
      "Group-derived thresholds lack the resolution to guide one athlete's day-to-day decisions.",
      "Rebelo et al., Sports Medicine 2026.",
    ]);
    s.addNotes(d.problem.notes);
  }

  // 3 — the insight. The deck names the visual; this direction draws it as a tolerance.
  {
    const { s, T } = sheet(pres, d, {
      n: 3, dark: true, title: d.insight.head,
      caption: "The noise floor — % change from this athlete's own baseline",
    });
    d.insight.visual(visualsFor(s, T, { x: 2.80, y: 1.10, w: 6.74 }));
    notes(s, T, deal(d.insight.foot, [3, 1, 1]));
    s.addNotes(d.insight.notes);
  }

  // 4 — the order of operations, dimensioned, and then the schedule of who does what.
  //     The first build put the three questions in a footnote under a title that
  //     promised them, and numbered four unordered roles instead.
  {
    const { s, T } = sheet(pres, d, {
      n: 4, dark: false, title: d.apply.head,
      caption: "On Monday — the order, then the schedule",
    });
    const qs = deal(d.apply.rule, [1, 1, 1]);
    const qw = 2.74, qgap = 0.40;
    dimension(s, {
      x0: PAD, x1: PAD + qw * 3 + qgap * 2, y: 1.22, color: T.accent,
      text: "In this order", size: 10, ext: 0.62, extTop: 1.14,
    });
    qs.forEach((q, i) => {
      const qx = PAD + i * (qw + qgap);
      if (i > 0) vrule(s, qx - qgap / 2, 1.14, 0.62, T.rule);
      label(s, `Q${i + 1}`, { x: qx, y: 1.34, w: qw, color: T.accent, size: 9, face: F.COND_MED });
      body(s, q, { x: qx, y: 1.52, w: qw, h: 0.40, size: 10, color: T.head });
    });

    hrule(s, PAD, 2.06, RIGHT - PAD, T.edge);
    label(s, "Role", { x: PAD, y: 2.14, w: 2.10, color: T.label, size: 8 });
    label(s, "What changes on Monday", { x: 2.80, y: 2.14, w: 6.74, color: T.label, size: 8 });
    hrule(s, PAD, 2.32, RIGHT - PAD, T.rule);

    let ry = 2.40;
    d.apply.columns.forEach((c) => {
      s.addText(c.who, {
        x: PAD, y: ry, w: 2.10, h: 0.44, fontSize: 10.5, fontFace: F.COND_MED,
        color: T.head, valign: "top", margin: 0, lineSpacingMultiple: 1.06,
      });
      body(s, c.what, { x: 2.80, y: ry, w: 6.74, h: 0.40, size: 9.5, color: T.body });
      ry += 0.38;
      hrule(s, PAD, ry - 0.06, RIGHT - PAD, T.rule);
    });

    notes(s, T, [
      "Applied Performance supplies evidence. Clearance is a medical decision.",
      "",
      "Rebelo et al., Sports Medicine 2026.",
    ]);
    s.addNotes(d.apply.notes);
  }

  // 5 — the one thing, bracketed by a dimension, with the question left open under it.
  {
    const { s, T } = sheet(pres, d, {
      n: 5, dark: true, title: "The one thing",
      caption: "The one thing — and the question to leave in the room",
    });
    const pTop = 1.20, pBot = 2.40;
    hrule(s, PAD, pTop, RIGHT - PAD, T.edge);
    hrule(s, PAD, pBot, RIGHT - PAD, T.edge);
    // A vertical dimension in the margin: the panel is a bracketed quantity, not a box.
    vrule(s, 0.36, pTop + 0.06, pBot - pTop - 0.12, T.accent);
    arrow(s, { x: 0.366, y: pTop + 0.07, dir: "left", color: T.accent, size: 0.09 });
    arrow(s, { x: 0.366, y: pBot - 0.07, dir: "right", color: T.accent, size: 0.09 });

    s.addText(d.takeaway.oneThing, {
      x: PAD + 0.14, y: 1.38, w: 8.76, h: 0.90, fontSize: 20, fontFace: F.COND_MED,
      color: T.display, valign: "top", margin: 0, lineSpacingMultiple: 1.08,
    });

    label(s, "For the room", { x: PAD, y: 2.56, w: 5.60, color: T.accent, size: 9 });
    body(s, d.takeaway.question,
      { x: PAD, y: 2.78, w: 5.60, h: 0.80, size: 12, color: T.head });

    notes(s, T, [
      "Where missing early maladaptation is the costlier mistake, the source supports a more sensitive threshold on purpose — not an argument for acting on less.",
      "Applied Performance supplies evidence. Clearance is a medical decision.",
      "Rebelo et al., Sports Medicine 2026.",
    ]);
    s.addNotes(d.takeaway.notes);
  }

  await pres.writeFile({ fileName: outPath });
  return outPath;
}

module.exports = { buildDeck, name: "shop-drawing" };

