85	// Every straight line on these sheets is a filled rect. pptxgenjs 4 writes a 1pt
86	// #333333 outline onto any shape that asks for no border, so nothing here asks for one.
87	function line(s, { x, y, w, h, color }) {
88	  s.addShape("rect", { x, y, w, h, fill: { color }, line: { color, width: 0.25 } });
89	}
90	const hrule = (s, x, y, w, color, t = HAIR) => line(s, { x, y, w, h: t, color });
