95	function arrow(s, { x, y, dir, color, size = 0.12 }) {
96	  s.addShape("triangle", {
97	    x: x - size / 2, y: y - size / 2, w: size, h: size,
98	    fill: { color }, line: { color, width: 0.25 },
99	    rotate: ARROW_ROT[dir],
100	  });
101	}
