103	/** A dimension: extension lines, a double-arrowed rule, and the value above it. */
104	function dimension(s, { x0, x1, y, color, text, size = 10, ext, extTop }) {
105	  if (ext) {
106	    vrule(s, x0, extTop, ext, color);
107	    vrule(s, x1, extTop, ext, color);
108	  }
109	  hrule(s, x0 + 0.06, y, x1 - x0 - 0.12, color);
110	  arrow(s, { x: x0 + 0.07, y: y + 0.006, dir: "left", color, size: 0.10 });
111	  arrow(s, { x: x1 - 0.07, y: y + 0.006, dir: "right", color, size: 0.10 });
112	  if (text) {
113	    s.addText(text.toUpperCase(), {
114	      x: (x0 + x1) / 2 - 1.2, y: y - 0.28, w: 2.4, h: 0.24, fontSize: size,
115	      fontFace: F.COND_MED, color, align: "center", charSpacing: 1.2,
116	      valign: "top", margin: 0,
117	    });
118	  }
119	}
