121	/** 45° section hatch, clipped to the rect. Drafting says "this region is excluded". */
122	function hatch(s, { x, y, w, h, step = 0.18, color, width = 0.5 }) {
123	  for (let k = -h; k < w; k += step) {
124	    const t0 = Math.max(-k, 0);
125	    const t1 = Math.min(w - k, h);
126	    if (t1 - t0 < 0.02) continue;
127	    s.addShape("line", {
128	      x: x + k + t0, y: y + t0, w: t1 - t0, h: t1 - t0,
129	      line: { color, width },
130	    });
131	  }
132	}
