134	/**
135	 * A drafting centreline: long dash, short dash, repeat.
136	 *
137	 * Heavier and brighter than any adjustable line on the sheet, on purpose. A datum is
138	 * measured and a threshold is chosen, and that distinction cannot rest on dash rhythm,
139	 * which does not survive a projector.
140	 */
141	function centreline(s, { x, y0, y1, color }) {
142	  let y = y0;
143	  let long = true;
144	  while (y < y1) {
145	    const seg = Math.min(long ? 0.17 : 0.05, y1 - y);
146	    vrule(s, x, y, seg, color, 0.020);
147	    y += seg + 0.055;
148	    long = !long;
149	  }
150	}
