166	/** Split prose into sentences, then group it into n cells. */
167	function deal(text, counts) {
168	  const parts = (text || "").match(/[^.]+\./g) || [text];
169	  const out = [];
170	  let i = 0;
171	  counts.forEach((n) => {
172	    out.push(parts.slice(i, i + n).join(" ").trim());
173	    i += n;
174	  });
175	  if (i < parts.length) out[out.length - 1] += ` ${parts.slice(i).join(" ").trim()}`;
176	  return out;
177	}
